-- Qaryati seed data. Every record cites its source: the English Wikipedia article of each village (which
-- cites the original censuses, the Ottoman registers and the Survey of Western Palestine), the censuses
-- themselves, UNESCO and ARIJ. Photos come from Wikimedia Commons; the author and licence are in alt_image.
-- Data checked by hand against these sources on 22 November 2026.
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;


-- Accounts for local use and tests (passwords: <role>-demo-2026). Change or remove them before any real deployment:
--   admin@qaryati.test, editor@qaryati.test, reviewer@qaryati.test, contributor@qaryati.test










-- Deir Sharaf (village 9) events keep their ids 17-30.


-- A date before the Common Era cannot be stored in a DATE column, so this event keeps its year in the text.

-- Same definition as migration 1795222800000-CreateCulturalPractices (which skips an existing table).
CREATE TABLE IF NOT EXISTS `cultural_practices` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `village_id` int unsigned NOT NULL,
  `category` varchar(40) NOT NULL,
  `name_ar` varchar(255) NOT NULL,
  `name_eng` varchar(255) DEFAULT NULL,
  `description_ar` text,
  `description_eng` text,
  `source_id` int unsigned DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_cp_village` (`village_id`),
  KEY `fk_cp_source` (`source_id`),
  CONSTRAINT `fk_cp_village` FOREIGN KEY (`village_id`) REFERENCES `village` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_cp_source` FOREIGN KEY (`source_id`) REFERENCES `sources` (`id`) ON DELETE SET NULL,
  CONSTRAINT `chk_cp_category` CHECK (`category` IN ('craft', 'food', 'agricultural-practice', 'custom', 'music-dance', 'dress', 'other'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;



-- Every seeded record gets a review entry as `pending`, so reviewers can verify or reject it through the API
-- like any other record (entity types are the resource names of the permission policy).
SELECT t.entity_type, t.entity_id, 'pending', 'Loaded from the seed; not reviewed yet.'
  FROM (
    SELECT 'source' AS entity_type, id AS entity_id FROM `sources`
    UNION ALL SELECT 'village', id FROM `village`
    UNION ALL SELECT 'village-name', id FROM `village_name`
    UNION ALL SELECT 'population-record', id FROM `population_records`
    UNION ALL SELECT 'historical-event', id FROM `historical_events`
    UNION ALL SELECT 'landmark', id FROM `landmarks`
    UNION ALL SELECT 'economic-activity', id FROM `economic_activities`
    UNION ALL SELECT 'facility', id FROM `facilities`
    UNION ALL SELECT 'agricultural-product', id FROM `agricultural_products`
    UNION ALL SELECT 'village-relation', id FROM `village_relations`
    UNION ALL SELECT 'cultural-practice', id FROM `cultural_practices`
  ) t
 WHERE NOT EXISTS (SELECT 1 FROM `verification` v WHERE v.entity_type = t.entity_type AND v.entity_id = t.entity_id);

COMMIT;
SET FOREIGN_KEY_CHECKS = 1;
