INSERT INTO `sources` (`id`, `title`, `author`, `organization`, `url`, `source_type`, `publication_date`, `accessed_at`, `notes_ar`, `notes_eng`, `related_villages`, `reference`) VALUES
  (1, 'Population, Housing and Establishments Census 2017', NULL, 'Palestinian Central Bureau of Statistics (PCBS)', 'https://www.pcbs.gov.ps', 'census', '2018-02-01', '2026-11-22 12:00:00', 'التعداد العام للسكان والمساكن والمنشآت 2017. أُخذت الأرقام كما تذكرها مقالات ويكيبيديا الإنجليزية لكل قرية.', 'Figures as cited in the English Wikipedia article of each village.', NULL, 'PCBS Census 2017'),
  (2, 'Palestine: Land of Olives and Vines - Cultural Landscape of Southern Jerusalem, Battir', 'UNESCO World Heritage Centre', 'UNESCO', 'https://whc.unesco.org/en/list/1492', 'website', '2014-06-20', '2026-11-22 12:00:00', 'صفحة تسجيل بتير على قائمة التراث العالمي.', 'World Heritage listing page for Battir.', NULL, 'UNESCO WHC 1492'),
  (3, 'Palestine: Report and General Abstracts of the Census of 1922', 'J. B. Barron', 'Government of Palestine', NULL, 'census', '1923-01-01', NULL, 'تعداد الانتداب البريطاني لعام 1922، كما تنقله مقالات ويكيبيديا.', 'British Mandate census of 1922, as cited in Wikipedia.', NULL, 'Barron 1923'),
  (4, 'Historical Geography of Palestine, Transjordan and Southern Syria in the Late 16th Century', 'Wolf-Dieter Hutteroth; Kamal Abdulfattah', 'Fränkische Geographische Gesellschaft', NULL, 'book', '1977-01-01', NULL, 'مرجع دفتر الضرائب العثماني لعام 1596.', 'Reference for the Ottoman tax register of 1596.', NULL, 'Hutteroth and Abdulfattah 1977'),
  (5, 'Census of Palestine 1931: Population of Villages, Towns and Administrative Areas', 'E. Mills', 'Government of Palestine', NULL, 'census', '1932-01-01', NULL, 'تعداد الانتداب البريطاني لعام 1931، كما تنقله مقالات ويكيبيديا.', 'British Mandate census of 1931, as cited in Wikipedia.', NULL, 'Mills 1932'),
  (6, 'Village Statistics, April 1945', 'Government of Palestine; republished by Sami Hadawi (1970)', 'Palestine Liberation Organization Research Center', NULL, 'archive', '1945-04-01', NULL, 'إحصاءات القرى لعام 1945 (تقديرات رسمية للسكان والأراضي)، كما تنقلها مقالات ويكيبيديا.', 'Official 1945 estimates of village population and land, as cited in Wikipedia.', NULL, 'Village Statistics 1945; Hadawi 1970'),
  (7, 'The Survey of Western Palestine: Memoirs of the Topography, Orography, Hydrography, and Archaeology', 'C. R. Conder; H. H. Kitchener', 'Palestine Exploration Fund', NULL, 'book', '1881-01-01', NULL, 'مسح فلسطين الغربية (1881-1883)، أوصاف القرى كما تنقلها مقالات ويكيبيديا.', 'Village descriptions of 1881-1883, as cited in Wikipedia.', NULL, 'Conder and Kitchener 1881-1883'),
  (8, 'First Census of Population and Housing, 1961', NULL, 'Government of Jordan, Department of Statistics', NULL, 'census', '1964-01-01', NULL, 'التعداد الأردني لعام 1961، كما تنقله مقالات ويكيبيديا.', 'Jordanian census of 1961, as cited in Wikipedia.', NULL, 'Government of Jordan 1964'),
  (9, 'Wikimedia Commons', NULL, 'Wikimedia Foundation', 'https://commons.wikimedia.org', 'website', NULL, '2026-11-22 12:00:00', 'مصدر صور القرى والمعالم. اسم المصوّر والرخصة مذكوران مع كل صورة.', 'Source of the village and landmark photos; the author and licence are given with each photo.', NULL, 'Wikimedia Commons'),
  (10, 'Deir Sharaf: population by census (PCBS 1997, 2007, 2017)', NULL, 'Palestinian Central Bureau of Statistics (via City Population)', 'https://www.citypopulation.de/en/palestine/westbank/nabulus/150810__deir_sharaf', 'census', '2017-12-31', '2026-11-22 12:00:00', NULL, NULL, NULL, 'City Population, Palestine / West Bank / Nablus, entry 150810'),
  (11, 'Deir Sharaf', NULL, 'Wikipedia', 'https://en.wikipedia.org/wiki/Deir_Sharaf', 'website', NULL, '2026-11-22 12:00:00', 'مقال ويكيبيديا الإنجليزية عن القرية، وهو يوثّق مصادره الأصلية.', 'English Wikipedia article on the village, which cites its original sources.', NULL, 'English Wikipedia, "Deir Sharaf", revision 1374302474, accessed 22 November 2026'),
  (12, 'Deir Sharaf Village Profile', 'Applied Research Institute - Jerusalem (ARIJ)', 'Applied Research Institute - Jerusalem (ARIJ)', 'http://vprofile.arij.org/nablus/pdfs/vprofile/Deir%20Sharaf_vp-en.pdf', 'article', NULL, '2026-11-22 12:00:00', NULL, 'Published in 2014; the exact date is not given.', NULL, 'Palestinian Localities Study, Nablus Governorate, 2014 (funded by AECID). Draws on the Deir Sharaf Village Council (2013), PCBS (2009), the Ministry of Agriculture (2010) and the Directorate of Education in Nablus (2012).'),
