INSERT INTO `village` (`id`, `current_name`, `name_origin_ar`, `name_origin_eng`, `english_name`, `eng_description`, `arabic_description`, `historical_overview_ar`, `historical_overview_eng`, `latitude`, `longitude`, `governorate_id`, `administrative_area`, `elevation_meters`, `land_area_dunums`, `record_status`, `image`, `alt_image`, `light`, `feature_to_homepage`) VALUES
  (1, 'سنجل', 'يُعتقد أن الاسم مأخوذ من بلدة سان جيل الفرنسية، موطن الكونت ريمون الرابع دي تولوز الذي خيّم هنا في الحملة الصليبية الأولى. وتشكّك المؤرخة ليفي-روبين في ذلك، وترى أن الاسم الأصلي «سنحل» وأن الصليبيين ربطوه بسان جيل بسبب الاسم العربي لا العكس.', 'Thought to come from Saint-Gilles, home town of Count Raymond of Toulouse, who camped here on the First Crusade. The historian Levy-Rubin doubts this: she proposes Sinhil as the original name, which led the Crusaders to link the place with Saint-Gilles rather than the reverse.', 'Sinjil', 'A Palestinian town in Ramallah and al-Bireh Governorate, 15.5 km north-east of Ramallah, bordered by Turmus Ayya, Al-Lubban ash-Sharqiya, Abwein, Jiljiliya and Al-Mazra''a ash-Sharqiya. Its population was 5,742 in the 2017 census.', 'بلدة فلسطينية في محافظة رام الله والبيرة، على بُعد 15.5 كم شمال شرق رام الله. تحدّها ترمسعيا من الشرق، واللبن الشرقية من الشمال، وعبوين وجلجليا من الغرب، والمزرعة الشرقية من الجنوب. بلغ عدد سكانها 5,742 نسمة في تعداد 2017.', 'عُثر فيها على كسر فخارية من العصر البرونزي والعصور البيزنطية والصليبية والأيوبية والمملوكية. كانت أبرشية صليبية تدفع العشور لكنيسة القيامة، ومسجدها القائم اليوم مبني على مخطط الكنيسة الصليبية. ظهرت في دفتر الضرائب العثماني لعام 1596 في ناحية القدس. وصفها مسح فلسطين الغربية (1882) بأنها قرية متوسطة الحجم فيها بيوت من طابقين وتحتها بساتين تين جميلة. وفق اتفاقية أوسلو صُنّف 13.8% من أراضيها مناطق (أ) و34.7% مناطق (ب) و51.5% مناطق (ج).', 'Pottery from the Bronze Age and the Byzantine, Crusader, Ayyubid and Mamluk periods has been found. It was a Crusader parish paying tithes to the Church of the Holy Sepulchre, and its present mosque follows the plan of the Crusader church. It appears in the 1596 Ottoman tax register in the nahiya of Quds. The Survey of Western Palestine (1882) described a village of moderate size with two-storey houses and fine fig gardens below. Under the Oslo Accords, 13.8% of its land is Area A, 34.7% Area B and 51.5% Area C.', 32.033056, 35.264167, 7, NULL, 795, NULL, 'published', 'https://upload.wikimedia.org/wikipedia/commons/thumb/d/d9/Sinjil4140.JPG/1280px-Sinjil4140.JPG', 'سنجل من الجهة الشمالية (עדירל, CC BY-SA 4.0, Wikimedia Commons)', NULL, 'no'),
  (2, 'دير استيا', 'سُمّيت نسبة إلى مقام «استيا» القريب، وهو بحسب الإثنوغرافي توفيق كنعان والمؤرخ موشيه شارون الاسم العربي للنبي إشعيا.', 'Named after the nearby tomb of Istiya, which according to the ethnographer Tawfiq Canaan and the historian Moshe Sharon is the Arabic name for Isaiah.', 'Deir Istiya', 'A Palestinian town in Salfit Governorate, 15 km south-west of Nablus and 6.6 km north of Salfit. It has one of the largest areas of olive groves, nearly 10,000 dunums, and a historic old town. Its population was 3,696 in the 2017 census.', 'بلدة فلسطينية في محافظة سلفيت، على بُعد 15 كم جنوب غرب نابلس و6.6 كم شمال سلفيت. من أكبر البلدات مساحةً بأشجار الزيتون، إذ تقارب 10,000 دونم، وتضم بلدة قديمة. بلغ عدد سكانها 3,696 نسمة في تعداد 2017.', 'عُثر فيها على كسر فخارية من العصر الحديدي الثاني والعصرين الصليبي-الأيوبي والمملوكي. عام 1394 أُلزمت بتقديم العدس وزيت الزيتون والطحين وقفًا للمسجد الإبراهيمي في الخليل بأمر السلطان المملوكي برقوق. في القرن السابع عشر كانت مع بيت وزن مقرًّا لعائلة القاسم التي حكمت جماعين ومعظم شرق لواء نابلس. وصفها مسح فلسطين الغربية (1882) بأنها قرية كبيرة على مرتفع تحيط بها كروم الزيتون. بين 1950 و1960 لُقّبت محليًا بـ«برلين الصغيرة» لنشاط الحزب الشيوعي فيها، وهاجر نحو نصف سكانها إلى الخليج بين 1967 و1990.', 'Pottery from Iron Age II and the Crusader/Ayyubid and Mamluk periods has been found. In 1394 the Mamluk sultan Barquq required it to supply lentils, olive oil and flour as a waqf for the Ibrahimi Mosque in Hebron. In the 17th century it was, with Beit Wazan, a seat of the Qasim family who controlled Jamma''in and most of eastern Sanjak Nablus. The Survey of Western Palestine (1882) described a large village on high ground surrounded by olive groves. From 1950 to 1960 it was locally called "Little Berlin" for its Communist Party activity, and between 1967 and 1990 nearly half its people emigrated to the Gulf.', 32.130556, 35.14, 6, NULL, 379, 36000, 'published', 'https://upload.wikimedia.org/wikipedia/commons/thumb/8/85/DeirIstiya4594_d91.JPG/1280px-DeirIstiya4594_d91.JPG', 'دير استيا من الجهة الشمالية (עדירל, CC BY-SA 4.0, Wikimedia Commons)', NULL, 'no'),
  (3, 'بتير', 'يحمل موقعها الأثري بقايا «بيتار»، آخر معاقل ثورة بار كوخبا على الرومان، ويُربط اسم القرية بها.', 'Its archaeological site holds the remains of Beitar, the last stronghold of the Bar Kokhba revolt against Rome, with which the village name is linked.', 'Battir', 'A Palestinian village in Bethlehem Governorate, 6.4 km west of Bethlehem and south-west of Jerusalem. It is known for its ancient terraces, a Roman-era irrigation system fed by seven springs, and the Battiri eggplant. It was inscribed on the World Heritage List in 2014. Its population was 4,696 in the 2017 census.', 'قرية فلسطينية في محافظة بيت لحم، على بُعد 6.4 كم غرب بيت لحم وجنوب غرب القدس. تشتهر بمدرجاتها الزراعية القديمة ونظام ري يعود إلى العصر الروماني تغذيه سبعة ينابيع، وبالباذنجان البتيري. سُجّلت على قائمة التراث العالمي عام 2014. بلغ عدد سكانها 4,696 نسمة في تعداد 2017.', 'سكنت المنطقة منذ العصور القديمة، وعُثر فيها على فسيفساء من أواخر العصر البيزنطي أو بداية العصر الإسلامي. ظهرت في دفتر الضرائب العثماني لعام 1596 في ناحية القدس. بعد حرب 1948 رُسم خط الهدنة بين سكة الحديد والقرية، وسُمح لأهلها بالاستمرار في فلاحة أراضيهم خلف الخط مقابل حماية السكة. ضُمّت إلى الأردن عام 1950، ثم احتُلّت عام 1967، وتديرها السلطة الفلسطينية منذ اتفاقية أوسلو الثانية. نالت جائزة من اليونسكو عام 2011 لحماية مشهدها الثقافي.', 'The area has been inhabited since antiquity, and a mosaic from the late Byzantine or early Islamic period was found here. It appears in the 1596 Ottoman tax register in the nahiya of Quds. After 1948 the armistice line was drawn between the railway and the village; villagers kept farming their land beyond it in return for protecting the line. It was annexed by Jordan in 1950, occupied in 1967, and has been administered by the Palestinian Authority since Oslo II. UNESCO awarded it a prize in 2011 for safeguarding its cultural landscape.', 31.724722, 35.136667, 10, NULL, NULL, 7419, 'published', 'https://upload.wikimedia.org/wikipedia/commons/thumb/4/4d/Battir-Land-of-Olives-and-Vines.jpg/1280px-Battir-Land-of-Olives-and-Vines.jpg', 'بتير، أرض الزيتون والكروم (Ali.batha, CC BY-SA 4.0, Wikimedia Commons)', NULL, 'yes'),
  (4, 'أرطاس', 'رأى لي سترينج أن «أرطاس» تحريف للكلمة اللاتينية Hortus أي البستان، بمعنى «الفردوس»، ومنها جاء اسم دير «الحديقة المغلقة» القريب. ورأى إ. هـ. بالمر أنه اسم علم.', 'Le Strange thought Urtas a corruption of the Latin hortus, "garden", with the same meaning as firdus (paradise), which also gave the nearby Hortus Conclusus convent its name. E. H. Palmer thought it a personal name.', 'Artas', 'A Palestinian village in Bethlehem Governorate, about 2.4 km south-west of Bethlehem near Solomon''s Pools, bordered by Hindaza, Dheisheh camp, Al-Khader and Wadi Rahhal. It is known for its springs and gardens and for its Lettuce Festival. Its population was 5,745 in the 2017 census.', 'قرية فلسطينية في محافظة بيت لحم، على بُعد نحو 2.4 كم جنوب غرب بيت لحم، قرب برك سليمان. تحدّها هندازة من الشرق ومخيم الدهيشة من الشمال والخضر من الغرب ووادي رحال من الجنوب. تشتهر بينابيعها وبساتينها وبمهرجان الخس. بلغ عدد سكانها 5,745 نسمة في تعداد 2017.', 'يشهد نقشان من العصرين الفاطمي والمملوكي على اهتمام الحكام بها وعلى غناها. عام 1227 أكّد البابا غريغوري التاسع منحها لكنيسة بيت لحم. كان أهلها حتى القرن التاسع عشر مسؤولين عن حراسة برك سليمان التي تنقل المياه إلى بيت لحم والقدس. درستها عالمة الأنثروبولوجيا الفنلندية هيلما غرانكفيست بين عشرينيات القرن العشرين و1931، فأصبحت من أكثر القرى الفلسطينية توثيقًا.', 'Two inscriptions from the Fatimid and Mamluk periods show the rulers'' interest in the village and its wealth. In 1227 Pope Gregory IX confirmed it had been given to the Church of Bethlehem. Until the 19th century its people guarded Solomon''s Pools, which carried water to Bethlehem and Jerusalem. The Finnish anthropologist Hilma Granqvist studied it from the 1920s to 1931, making it one of the best documented Palestinian villages.', 31.689167, 35.186111, 10, NULL, 732, 4304, 'published', 'https://upload.wikimedia.org/wikipedia/commons/thumb/f/ff/Artas1b.jpg/1280px-Artas1b.jpg', 'أرطاس، صورة تاريخية من مجموعة ماتسون (matson-collection, Public domain, Wikimedia Commons)', NULL, 'yes'),
  (5, 'بيتا', 'معنى الاسم «البيت».', 'The name means "home".', 'Beita', 'A Palestinian town in Nablus Governorate, 13 km south-east of Nablus, made up of five clans branching into thirty families, with four mosques and three clinics. Its population was 11,682 in the 2017 census.', 'بلدة فلسطينية في محافظة نابلس، على بُعد 13 كم جنوب شرق نابلس، تتكون من خمس حمائل تتفرع إلى ثلاثين عائلة، وفيها أربعة مساجد وثلاث عيادات. بلغ عدد سكانها 11,682 نسمة في تعداد 2017.', 'عُثر في بيتا الفوقا وبيتا التحتا على كسر فخارية من العصر الحديدي الثاني والعصور الفارسية والرومانية والبيزنطية والمملوكية والعثمانية المبكرة، وفيها بيوت تعود إلى العصر الروماني. ظهرت في دفتر الضرائب العثماني لعام 1596 في ناحية جبل قبال من لواء نابلس. ذكرها إدوارد روبنسون عام 1838 «قرية كبيرة» في ناحية البيتاوي، ووصفها مسح فلسطين الغربية (1882) بأنها قاعدة الناحية المسمّاة باسمها. منذ 1967 قُتل أكثر من 77 من أهلها برصاص القوات الإسرائيلية، بينهم سبعة بين أيار وأيلول 2021 خلال الاحتجاج على بؤرة «أفيتار» الاستيطانية على أراضيها.', 'Pottery from Iron Age II and the Persian, Roman, Byzantine, Mamluk and early Ottoman periods has been found at Beita el-Fauqa and Beita et-Tahta, and some houses date to the Roman era. It appears in the 1596 Ottoman tax register in the nahiya of Jabal Qubal, Liwa of Nablus. Edward Robinson noted a "large village" in the El-Beitawy district in 1838, and the Survey of Western Palestine (1882) called it the capital of the district named after it. Since 1967 more than 77 of its people have been killed by Israeli forces, seven of them between May and September 2021 during protests against the Evyatar outpost on its land.', 32.143611, 35.2875, 4, NULL, NULL, NULL, 'published', 'https://upload.wikimedia.org/wikipedia/commons/thumb/0/06/Beita_village.jpg/1280px-Beita_village.jpg', 'بلدة بيتا (שי קנדלר, CC BY-SA 4.0, Wikimedia Commons)', NULL, 'no'),
  (6, 'عقربا', NULL, NULL, 'Aqraba', 'A Palestinian town in Nablus Governorate, 18 km south-east of Nablus, surrounded by hamlets seen as its extensions: al-Arama, al-Kroom, Abu ar-Reisa, ar-Rujman, Firas ad-Din and Tell al-Khashaba. About 62% of its land is olive and almond groves. Its population was 10,024 in the 2017 census.', 'بلدة فلسطينية في محافظة نابلس، على بُعد 18 كم جنوب شرق نابلس، تحيط بها خِرَب تُعدّ امتدادًا لها: العرمة والكروم وأبو الريسة والرجمان وفرس الدين وتل الخشبة. نحو 62% من أراضيها مزروع بالزيتون واللوز. بلغ عدد سكانها 10,024 نسمة في تعداد 2017.', 'كانت بلدة مهمة في العصر الروماني ومركزًا لمقاطعة سُمّيت باسمها عند يوسيفوس. سكنها مسيحيون في العصر البيزنطي وكان فيها ديران، ومسجدها مبني على بقايا كنيسة. من آثارها الوسيطة «الحصن» على أعلى نقطة فيها وبركة في وسطها ونقش عربي من عام 1414. سجّلها الإحصاء العثماني لعام 1596 بـ102 أسرة. وصفها مسح فلسطين الغربية (1882) بأنها قرية كبيرة تحيط بها أشجار الزيتون وبيوتها أحسن بناءً من معظم بيوت البلاد.', 'It was an important town in the Roman period and gave its name to a toparchy mentioned by Josephus. In the Byzantine period it was Christian, with two monasteries, and its mosque stands on the remains of a church. Medieval remains include al-Hisn, "the castle", on its highest point, a pool in its centre and an Arabic inscription of 1414. The Ottoman census of 1596 recorded 102 households. The Survey of Western Palestine (1882) described a large village surrounded with olives, with houses better built than most in the country.', 32.126389, 35.343611, 4, NULL, NULL, 34659, 'published', 'https://upload.wikimedia.org/wikipedia/commons/thumb/9/9f/Aqraba%2C_Nablus7443.JPG/1280px-Aqraba%2C_Nablus7443.JPG', 'عقربا من الجهة الجنوبية (יעקב, CC BY-SA 4.0, Wikimedia Commons)', NULL, 'no'),
  (7, 'جفنا', 'عُرفت باسم «جوفنا» زمن الحرب اليهودية الرومانية الأولى، وأصبحت بعد ذلك مركزًا إداريًا رومانيًا.', 'Known as Gophna at the time of the First Jewish-Roman War, after which it became a Roman regional capital.', 'Jifna', 'A Palestinian village in Ramallah and al-Bireh Governorate, 8 km north of Ramallah and 23 km north of Jerusalem, with a Christian majority since the 6th century. Of its 6,015 dunums, 420 are built up and most of the rest is olive, fig and apricot groves. It is known for its apricot festival. Its population was 2,919 in the 2017 census.', 'قرية فلسطينية في محافظة رام الله والبيرة، على بُعد 8 كم شمال رام الله و23 كم شمال القدس، ذات أغلبية مسيحية منذ القرن السادس. مساحتها 6,015 دونمًا، 420 منها مبنية ومعظم الباقي مزروع بالزيتون والتين والمشمش. تشتهر بمهرجان المشمش. بلغ عدد سكانها 2,919 نسمة في تعداد 2017.', 'وصفها يوسيفوس بأنها المدينة الثانية في اليهودية بعد القدس، وأصبحت عاصمة مقاطعة رومانية. بُنيت فيها كنيسة القديس جورجيوس في القرن السادس فصارت بلدة مسيحية في العهد البيزنطي، وازدهرت لوقوعها على طريق تجاري. ظهرت في دفتر الضرائب العثماني لعام 1596 باسم «جفنا النصارى» بـ21 أسرة، وكانت القرية الوحيدة المسيحية بالكامل في ناحية بني زيد. استخدم العثمانيون برجها القديم سجنًا في القرن التاسع عشر، وبُنيت فيها كنيسة أرثوذكسية عام 1858.', 'Josephus called it the second city of Judea after Jerusalem, and it became the capital of a Roman toparchy. The Church of St George was built in the 6th century, by which time it was a Christian town, prospering on a trade route. The 1596 Ottoman register lists "Jifna an-Nasara" with 21 households; it was the only all-Christian village of the Bani Zeid subdistrict. The Ottomans used its old tower as a jail in the 19th century, and an Orthodox church was built in 1858.', 31.961944, 35.215556, 7, 'Jifna Village Council', NULL, 6015, 'published', 'https://upload.wikimedia.org/wikipedia/commons/thumb/e/e2/Jifna4462.jpg/1280px-Jifna4462.jpg', 'جفنا (יעקב, CC BY-SA 3.0, Wikimedia Commons)', NULL, 'yes'),
  (8, 'بديا', NULL, NULL, 'Biddya', 'A Palestinian town in Salfit Governorate, 32 km south-west of Nablus and 10 km north-west of Salfit, on the western ridge of the central mountain range. Its economy rests on olives for oil and Nabulsi soap, and it has four mosques and three health clinics. Its population was 10,451 in the 2017 census.', 'بلدة فلسطينية في محافظة سلفيت، على بُعد 32 كم جنوب غرب نابلس و10 كم شمال غرب سلفيت، على السفح الغربي للسلسلة الجبلية الوسطى. يعتمد اقتصادها على الزيتون لإنتاج الزيت والصابون النابلسي، وفيها أربعة مساجد وثلاث عيادات. بلغ عدد سكانها 10,451 نسمة في تعداد 2017.', 'عُثر فيها على كسر فخارية من العصر الحديدي الثاني والعصرين البيزنطي-الأموي والصليبي-الأيوبي. ظهرت في دفتر الضرائب العثماني لعام 1596 في ناحية جبل قبال من لواء نابلس. وصفها مسح فلسطين الغربية (1882) بأنها قرية متوسطة الحجم بيوتها من الحجر تحيط بها بساتين زيتون قديمة جميلة، وتعتمد على آبار منحوتة في الصخر.', 'Pottery from Iron Age II and the Byzantine/Umayyad and Crusader/Ayyubid periods has been found. It appears in the 1596 Ottoman tax register in the nahiya of Jabal Qubal, Liwa of Nablus. The Survey of Western Palestine (1882) described a village of moderate size, its houses mostly of stone, surrounded by fine old olive groves and supplied by rock-cut cisterns.', 32.114167, 35.0775, 6, 'Biddya Municipality', 359, NULL, 'published', 'https://upload.wikimedia.org/wikipedia/commons/thumb/2/2d/Arch%C3%A9ologie_et_monuments.jpg/1280px-Arch%C3%A9ologie_et_monuments.jpg', 'البلدة القديمة في بديا (Yaqueen, CC BY-SA 4.0, Wikimedia Commons)', NULL, 'no'),
  (9, 'دير شرف', 'يذكر المجلس القروي (عبر ملف أريج، 2014) أن القرية سُمّيت نسبة إلى «شرف»، أحد قادة جيش صلاح الدين بعد تحرير سبسطية. أما مسح فلسطين الغربية (بالمر، 1881) فيفسّر الاسم بـ«دير الأشراف».', 'The village council (via the ARIJ profile, 2014) says it was named after "Sharaf", one of the leaders of Salah ad-Din''s army, after Sabastiya was taken. The Survey of Western Palestine name lists (Palmer, 1881) render it "the monastery of the nobles".', 'Deir Sharaf', 'A Palestinian village in Nablus Governorate, 7.8 km northwest of Nablus at about 320 m above sea level. It is bordered by An Naqura, Beit Iba and Sabastiya to the east, Burqa and Ramin to the north, Beit Lid to the west and Qusin to the south. Its area is about 7,745 dunums, and it is known for olives, which cover some 3,295 dunums. A village council has governed it since 1964.', 'قرية فلسطينية في محافظة نابلس، تقع على بُعد 7.8 كم شمال غرب مدينة نابلس، على ارتفاع نحو 320 م عن سطح البحر. تحدّها الناقورة وبيت إيبا وسبسطية من الشرق، وبرقة ورامين من الشمال، وبيت ليد من الغرب، وقوصين من الجنوب. تبلغ مساحتها نحو 7,745 دونمًا، وتشتهر بزراعة الزيتون الذي يغطي قرابة 3,295 دونمًا. يدير شؤونها مجلس قروي منذ عام 1964.', 'عُثر في القرية على كسر فخارية من العصر الحديدي الثاني والعصر البيزنطي والعصرين الإسلامي المبكر والوسيط. دخلت تحت الحكم العثماني عام 1517، وظهرت في سجل الضرائب العثماني لعام 1596 في ناحية جبل سامي بلواء نابلس بـ55 أسرة مسلمة. وصفها مسح فلسطين الغربية (1882) بأنها قرية صغيرة في منخفض، فوقها نبع دائم تُروى منه حدائق الخضار، ويزرع حولها التين والزيتون. خضعت للحكم الأردني بعد عام 1948، ثم للاحتلال الإسرائيلي منذ عام 1967. وفق اتفاقية أوسلو الثانية (1995) صُنّف 24% من أراضيها مناطق (ب) و76% مناطق (ج)، وصودر من أراضيها 236 دونمًا لمستوطنة «شافي شومرون». يذكر المجلس القروي أن أصول السكان تعود إلى الوعرة وطبريا وكفر عقب.', 'Pottery from Iron Age II, the Byzantine, early Muslim and medieval periods has been found in the village. It came under Ottoman rule in 1517 and appears in the 1596 Ottoman tax register in the nahiya of Jabal Sami, Liwa of Nablus, with 55 Muslim households. The Survey of Western Palestine (1882) described a small village in a hollow, with a perennial spring above it watering vegetable gardens, and figs and olives around it. It came under Jordanian rule after 1948 and under Israeli occupation in 1967. Under the Oslo II Accord (1995), 24% of its land became Area B and 76% Area C, and 236 dunums were confiscated for the settlement of Shavei Shomron. The village council says the families came originally from Al Wa''ara, Tiberias and Kafr ''Aqab.', 32.254167, 35.188056, 4, 'Deir Sharaf Village Council', 320, 7745, 'published', 'https://upload.wikimedia.org/wikipedia/commons/thumb/8/8e/DeirSharaf7859_d58.JPG/1280px-DeirSharaf7859_d58.JPG', 'دير شرف (יעקב, CC BY-SA 4.0, Wikimedia Commons)', NULL, 'yes'),
  (10, 'سبسطية', 'سمّاها هيرودس الكبير «سبسطية» تكريمًا للإمبراطور أغسطس، فالكلمة اليونانية «سيباستوس» (الموقَّر) ترجمة للقب «أغسطس». ويحفظ الاسم الحالي الاسم الروماني «سيباستي».', 'Herod the Great renamed the city Sebastia in honour of the emperor Augustus: the Greek sebastos, "venerable", translates the Latin augustus. The modern name preserves the Roman Sebaste.', 'Sebastia', 'A Palestinian village in Nablus Governorate, about 12 km north-west of Nablus, one of the oldest continuously inhabited places in the West Bank. It holds the remains of ancient Samaria and the Roman city, and the Nabi Yahya Mosque, held to contain the tomb of John the Baptist. UNESCO inscribed it on the World Heritage List in 2026. Its population was 3,205 in the 2017 census.', 'قرية فلسطينية في محافظة نابلس، على بُعد نحو 12 كم شمال غرب نابلس، من أقدم الأماكن المأهولة باستمرار في الضفة الغربية. فيها آثار السامرة القديمة والمدينة الرومانية، ومسجد النبي يحيى الذي يُعتقد أنه يضم قبر يوحنا المعمدان. أدرجتها اليونسكو على قائمة التراث العالمي عام 2026. بلغ عدد سكانها 3,205 نسمة في تعداد 2017.', 'عُرفت في القرن التاسع قبل الميلاد باسم السامرة، عاصمة مملكة إسرائيل الشمالية، حتى دمّرها الآشوريون نحو 720 ق.م. أعاد هيرودس الكبير بناءها عام 27 ق.م وسمّاها سبسطية، وبنى فيها معبدًا لأغسطس وملعبًا. منذ القرن الرابع يعدّها المسيحيون والمسلمون موضع قبر يوحنا المعمدان (النبي يحيى)، وكانت مقرًّا لأسقف في المملكة الصليبية. ظهرت في دفتر الضرائب العثماني لعام 1596 في ناحية جبل سامي. نقّبت فيها بعثة هارفارد (1908-1910) ثم البعثة المشتركة بقيادة جون كروفوت (1931-1935).', 'In the 9th century BCE it was Samaria, capital of the northern Kingdom of Israel, until the Assyrians destroyed it around 720 BCE. Herod the Great rebuilt it in 27 BCE as Sebastia, with a temple to Augustus and a stadium. Since the 4th century Christians and Muslims have held it to be the burial place of John the Baptist, and it was the seat of a bishop in the Crusader kingdom. It appears in the 1596 Ottoman tax register in the nahiya of Jabal Sami. It was excavated by the Harvard Expedition (1908-1910) and the Joint Expedition under John Crowfoot (1931-1935).', 32.276667, 35.195833, 4, NULL, NULL, 4810, 'published', 'https://upload.wikimedia.org/wikipedia/commons/thumb/2/27/2016_WLM_-_OVEDC_-_Ancient_Roman_theatre_of_Sebastia_033.jpg/1280px-2016_WLM_-_OVEDC_-_Ancient_Roman_theatre_of_Sebastia_033.jpg', 'المدرج الروماني في سبسطية (Ovedc, CC BY-SA 4.0, Wikimedia Commons)', NULL, 'yes'),
  (11, 'عابود', NULL, NULL, 'Aboud', 'A Palestinian village in Ramallah and al-Bireh Governorate, north-west of Ramallah and 30 km north of Jerusalem, near al-Lubban and Bani Zeid. Its Church of St Mary goes back to the Byzantine period. Its economy has centred on olives; its products are olive oil, olive soap, dried figs and almonds. Its population was 2,153 in the 2017 census.', 'قرية فلسطينية في محافظة رام الله والبيرة، شمال غرب رام الله وعلى بُعد 30 كم شمال القدس، يجاورها اللبن الغربي وبني زيد. فيها كنيسة القديسة مريم التي تعود أصولها إلى العصر البيزنطي. اقتصادها قائم تاريخيًا على الزيتون، ومن منتجاتها الزيت والصابون والتين المجفف واللوز. بلغ عدد سكانها 2,153 نسمة في تعداد 2017.', 'عُثر فيها على آثار من العصور الرومانية والبيزنطية والصليبية والأيوبية والمملوكية والعثمانية. كان فيها مجتمع مسيحي بارز في العهد البيزنطي، واحتفظ أهلها بالآرامية للطقوس الدينية بعد التعريب. سمّاها الصليبيون «كازال سانتا ماريا»، وبُني جزؤها الجنوبي في العصر المملوكي وفيه ضريحان مزخرفان. تشير السجلات العثمانية إلى أغلبية مسيحية في القرن السادس عشر استمرت حتى القرن التاسع عشر. وصفها مسح فلسطين الغربية (1882) بأنها قرية مسيحية كبيرة مزدهرة من الحجر.', 'Remains from the Roman, Byzantine, Crusader, Ayyubid, Mamluk and Ottoman periods have been found. It had a prominent Christian community in the Byzantine era, and kept Aramaic for liturgy after Arabization. The Crusaders called it Casale Santa Maria; its southern part, with two ornate mausoleums, dates from the Mamluk period. Ottoman records show a Christian majority in the 16th century that lasted into the 19th. The Survey of Western Palestine (1882) described a large and flourishing Christian village of stone.', 32.015, 35.068056, 7, NULL, NULL, 15000, 'published', 'https://upload.wikimedia.org/wikipedia/commons/thumb/b/bb/Abud8815.JPG/1280px-Abud8815.JPG', 'عابود من الجهة الجنوبية (יעקב, CC BY-SA 3.0, Wikimedia Commons)', NULL, 'no'),
  (12, 'وادي فوكين', NULL, NULL, 'Wadi Fukin', 'A Palestinian village in Bethlehem Governorate, 8 km south-west of Bethlehem, between the Green Line and the separation barrier. Farming is its main income: 11 springs water hundreds of small plots through canals and dams, and its produce is known for its quality. It has two elementary schools, a mosque, a pharmacy and a clinic. Its population was 1,342 in the 2017 census.', 'قرية فلسطينية في محافظة بيت لحم، على بُعد 8 كم جنوب غرب بيت لحم، بين الخط الأخضر وجدار الفصل. تعتمد على الزراعة مصدرًا رئيسيًا للدخل، وتروي مئات القطع الصغيرة من 11 نبعًا عبر قنوات وسدود، وتشتهر بجودة منتجاتها. فيها مدرستان أساسيتان ومسجد وصيدلية وعيادة. بلغ عدد سكانها 1,342 نسمة في تعداد 2017.', 'عُثر في المنطقة على بقايا كنيسة صغيرة وآبار ومدافن صخرية وفخار بيزنطي، وفي خربة عين الكنيسة شرقها بقايا كنيسة بُنيت على مرحلتين بين القرن الخامس والحادي عشر. ظهرت في الإحصاء العثماني لعام 1596 باسم «فوقين» في ناحية القدس. وصفها مسح فلسطين الغربية (1883) بأنها قرية حجرية صغيرة فيها نبع جيد وبساتين برتقال وليمون. هُجّر أهلها عام 1949 وقررت لجنة الهدنة المشتركة عودتهم، لكنهم وجدوا بيوتهم مهدّمة وأُجبروا على المغادرة ثانية، ولم يعودوا إلا عام 1972.', 'Remains of a chapel, cisterns, rock-cut tombs and Byzantine pottery have been found, and at Khirbet Ain al-Kanisah to the east are the remains of a church built in two phases between the 5th and 11th centuries. The 1596 Ottoman census lists it as Fuqin in the nahiya of Quds. The Survey of Western Palestine (1883) described a small stone village with a good spring and orange and lemon gardens. Its people were expelled in 1949; the Mixed Armistice Commission ruled they could return, but they found their houses destroyed and were forced out again, returning only in 1972.', 31.706667, 35.103889, 10, 'Wadi Fukin Village Council', NULL, 4347, 'published', 'https://upload.wikimedia.org/wikipedia/commons/thumb/9/9b/Wadi_Fukin.jpg/1280px-Wadi_Fukin.jpg', 'وادي فوكين في الوادي (Davidbena, CC BY-SA 4.0, Wikimedia Commons)', NULL, 'no'),
  (13, 'بيرزيت', '«بير زيت» أي «بئر الزيت»، ويرجّح أنه يعود إلى العصرين الروماني والبيزنطي، إذ كان زيت الزيتون يُخزَّن في آبار محفورة في الأرض. ما زالت ست من هذه الآبار في البلدة القديمة.', 'Bir zeit means "well of [olive] oil", likely from Roman and Byzantine times when olive oil was stored in wells dug into the ground; six such wells remain in the historic centre.', 'Birzeit', 'A predominantly Christian Palestinian town in Ramallah and al-Bireh Governorate, 7.5 km north of Ramallah, bordered by Jifna and Ein Siniya to the east and Atara to the north. It is home to Birzeit University and about 200 historic buildings, over 100 of them in the old town. Its population was 5,878 in the 2017 census.', 'بلدة فلسطينية ذات أغلبية مسيحية في محافظة رام الله والبيرة، على بُعد 7.5 كم شمال رام الله، تحدّها جفنا وعين سينيا من الشرق وعطارة من الشمال. فيها جامعة بيرزيت ونحو 200 مبنى تاريخي، أكثر من مئة منها في البلدة القديمة. بلغ عدد سكانها 5,878 نسمة في تعداد 2017.', 'عُثر فيها على كسر فخارية من العصر الحديدي الثاني والعصور الهلنستية والرومانية والبيزنطية والمملوكية، وفي خربة بير زيت غربها بقايا مبنى من العصر الصليبي. ظهرت في دفتر الضرائب العثماني لعام 1596 باسم «بير زيت» بـ26 أسرة. وصفها مسح فلسطين الغربية (1882) بأنها قرية مسيحية متوسطة فيها كنيسة يونانية وكنيسة لاتينية تحيط بها أشجار الزيتون. تأسست كنيسة سيدة السلام (غوادالوبي) عام 1858. بعد اتفاقيات 1995 صُنّف 75.8% من أراضيها مناطق (ب).', 'Pottery from Iron Age II and the Hellenistic, Roman, Byzantine and Mamluk periods has been found, and at Khirbat Bir Zait to the west are the remains of a Crusader-era building. The 1596 Ottoman register lists Bir Zayt with 26 households. The Survey of Western Palestine (1882) described a Christian village of moderate size with a Greek and a Latin church, surrounded by olives. The Church of Our Lady Queen of Peace (Guadalupe) was founded in 1858. After the 1995 accords, 75.8% of its land became Area B.', 31.972222, 35.195556, 7, 'Birzeit Municipality', 788, 14077, 'published', 'https://upload.wikimedia.org/wikipedia/commons/thumb/6/6c/Amjg.dtp0732.jpg/1280px-Amjg.dtp0732.jpg', 'منظر عام لبيرزيت عام 2020 (Dr. Mohmad, CC BY-SA 4.0, Wikimedia Commons)', NULL, 'yes'),
  (14, 'الجيب', 'تُطابَق الجيب مع مدينة جبعون الكنعانية القديمة، ومعنى الجذر «جِب»: الحفرة أو الخندق.', 'Al-Jib is identified with the ancient Canaanite city of Gibeon, from the root geb, "pit, ditch".', 'Al Jib', 'A Palestinian village in Jerusalem Governorate, 9.5 km north-west of Jerusalem, bordered by Bir Nabala and al-Judeira to the east and Beituniya to the north. About 90% of its land is Area C, and the barrier cut its al-Khalayleh neighbourhood off from the rest. Its population was 3,862 in the 2017 census.', 'قرية فلسطينية في محافظة القدس، على بُعد 9.5 كم شمال غرب القدس، تحدّها بير نبالا والجديرة من الشرق وبيتونيا من الشمال. نحو 90% من أراضيها مصنّف مناطق (ج)، وفصل الجدار حي الخلايلة عن بقيتها. بلغ عدد سكانها 3,862 نسمة في تعداد 2017.', 'جبعون مدينة ازدهرت في أواخر العصر الحديدي الثاني بتحصينات قوية ومعصرة نبيذ ونظام مياه متطور. أول من طابقها بالجيب إدوارد روبنسون عام 1838، وأكّدت ذلك حفريات جيمس بريتشارد (1956-1959) التي عثرت على 56 مقبض جرّة منقوشًا باسم «جبعون». توقف صلاح الدين فيها عام 1187 بعد تحرير القدس. ظهرت في دفتر الضرائب العثماني لعام 1596 في ناحية جبل القدس. منذ 1967 صودر 26.6% من أراضيها لإقامة مستوطنات.', 'Gibeon prospered in late Iron Age II, with strong fortifications, a winery and an advanced water system. Edward Robinson identified it with al-Jib in 1838, and James Pritchard''s excavations (1956-1959) confirmed this with 56 jar handles inscribed "gb''n". Saladin halted here in 1187 after the fall of Jerusalem. It appears in the 1596 Ottoman tax register in the nahiya of Jabal Quds. Since 1967, 26.6% of its land has been confiscated for settlements.', 31.851389, 35.184444, 9, NULL, 739, 9879, 'published', 'https://upload.wikimedia.org/wikipedia/commons/thumb/7/79/Eljibcenter9840.JPG/1280px-Eljibcenter9840.JPG', 'وسط الجيب من مقام النبي صموئيل (יעקב, CC BY-SA 3.0, Wikimedia Commons)', NULL, 'no');
