INSERT INTO `agricultural_products` (`id`, `name_ar`, `description_ar`, `name_eng`, `description_eng`) VALUES
  (1, 'الزيتون', 'من أهم المحاصيل في القرى الفلسطينية، ويُعصر لإنتاج الزيت.', 'Olives', 'One of the main crops of Palestinian villages, pressed for oil.'),
  (2, 'العنب', 'يُزرع في المناطق الجبلية، ويُؤكل طازجًا أو يُصنع منه الدبس.', 'Grapes', 'Grown in the hills, eaten fresh or made into grape syrup.'),
  (3, 'اللوز', 'أشجار تزهر في أواخر الشتاء.', 'Almonds', 'Trees that bloom in late winter.'),
  (4, 'التين', 'يُزرع في البساتين وعلى المدرجات ويُجفف.', 'Figs', 'Grown in orchards and on terraces, and dried.'),
  (5, 'الباذنجان البتيري', 'صنف محلي من بتير، مستطيل بنفسجي فاتح بلبّ أبيض قليل البذور.', 'Battiri eggplant', 'A local variety from Battir, elongated and light purple with seedless white flesh.'),
  (6, 'القمح', 'محصول حبوب بعلي، ورد في الضرائب العثمانية على معظم القرى.', 'Wheat', 'A rain-fed grain, taxed in most villages in the Ottoman registers.'),
  (7, 'الخضروات', 'خضروات موسمية مروية.', 'Vegetables', 'Seasonal irrigated vegetables.'),
  (8, 'الزعتر', 'نبات عطري يُجمع من البراري ويُزرع أيضًا.', 'Thyme', 'An aromatic herb gathered wild and also grown.'),
  (9, 'البامية', 'خضار صيفية.', 'Okra', 'A summer vegetable.'),
  (10, 'الفقوس', 'خضار صيفية بعلية.', 'Snake cucumber', 'A rain-fed summer vegetable.'),
  (11, 'المشمش', 'فاكهة موسمها قصير في أواخر الربيع.', 'Apricots', 'A fruit with a brief season in late spring.'),
  (12, 'الخس', 'خضار شتوية، ولها مهرجان سنوي في أرطاس.', 'Lettuce', 'A winter vegetable, celebrated by an annual festival in Artas.'),
  (13, 'الحمضيات', 'البرتقال والليمون في البساتين المروية قرب الينابيع.', 'Citrus', 'Oranges and lemons in irrigated gardens near springs.'),
  (14, 'الشعير', 'محصول حبوب بعلي.', 'Barley', 'A rain-fed grain.');
