INSERT INTO `landmarks` (`id`, `village_id`, `name_ar`, `name_eng`, `type`, `description_ar`, `description_eng`, `images`, `source_id`) VALUES
  (9, 9, 'المسجد القديم (مسجد عمر بن الخطاب)', 'Old Mosque (Umar ibn al-Khattab)', 'religious_site', 'المسجد القديم في القرية. لاحظ الرحالة فكتور غيرين عام 1870 ساحة صغيرة أمام المسجد مرصوفة ببلاطات قديمة.', 'The village''s old mosque. In 1870 Victor Guérin noted a small square in front of the mosque paved with ancient slabs.', NULL, 12),
  (10, 9, 'المسجد الجديد (مسجد خالد بن الوليد)', 'New Mosque (Khalid ibn al-Walid)', 'religious_site', 'المسجد الثاني في القرية.', 'The village''s second mosque.', NULL, 12),
  (11, 9, 'خربة الوعرة', 'Kherba Al Wara''a', 'archaeological_site', 'من المواقع الأثرية في القرية، وتحتاج إلى ترميم لتصبح موقعًا سياحيًا وفق وزارة السياحة والآثار.', 'An archaeological site of the village; it needs restoration to qualify as a tourist site, according to the Ministry of Tourism and Antiquities.', NULL, 12),
  (12, 9, 'خربة قابوبا', 'Kherba Kaboba', 'archaeological_site', 'من المواقع الأثرية في القرية، وتحتاج إلى ترميم لتصبح موقعًا سياحيًا وفق وزارة السياحة والآثار.', 'An archaeological site of the village; it needs restoration to qualify as a tourist site, according to the Ministry of Tourism and Antiquities.', NULL, 12),
  (13, 9, 'خربة بيت جديا', 'Kherba Beit Jedea', 'archaeological_site', 'من المواقع الأثرية في القرية، وتحتاج إلى ترميم لتصبح موقعًا سياحيًا وفق وزارة السياحة والآثار.', 'An archaeological site of the village; it needs restoration to qualify as a tourist site, according to the Ministry of Tourism and Antiquities.', NULL, 12),
  (14, 9, 'خربة قوصين الساحل', 'Kherba Qusin Al Sahel', 'archaeological_site', 'من المواقع الأثرية في القرية، وتحتاج إلى ترميم لتصبح موقعًا سياحيًا وفق وزارة السياحة والآثار.', 'An archaeological site of the village; it needs restoration to qualify as a tourist site, according to the Ministry of Tourism and Antiquities.', NULL, 12),
  (15, 9, 'خربة المشعبات', 'Kherba Al Mash''abat', 'archaeological_site', 'من المواقع الأثرية في القرية، وتحتاج إلى ترميم لتصبح موقعًا سياحيًا وفق وزارة السياحة والآثار.', 'An archaeological site of the village; it needs restoration to qualify as a tourist site, according to the Ministry of Tourism and Antiquities.', NULL, 12),
  (16, 9, 'خربة الكفرات', 'Kherba Al Kafarat', 'archaeological_site', 'من المواقع الأثرية في القرية، وتحتاج إلى ترميم لتصبح موقعًا سياحيًا وفق وزارة السياحة والآثار.', 'An archaeological site of the village; it needs restoration to qualify as a tourist site, according to the Ministry of Tourism and Antiquities.', NULL, 12),
  (NULL, 1, 'مسجد سنجل (الكنيسة الصليبية)', 'Sinjil mosque (former Crusader church)', 'historic_building', 'مسجد القرية مبني على مخطط الكنيسة الصليبية التي كانت كنيسة الأبرشية في القرن الثاني عشر.', 'The village mosque follows the plan of the Crusader church that served the parish in the 12th century.', NULL, 13),
  (NULL, 1, 'مقام أبو عوف', 'Maqam Abu Auf', 'religious_site', 'مقام لرجل صالح يُنسب إلى زمن الخليفة عمر بن الخطاب.', 'Shrine of a holy man said to date from the time of Caliph Umar ibn al-Khattab.', NULL, 13),
  (NULL, 1, 'بئر يوسف', 'Well of Joseph', 'cultural_site', 'وثّق توفيق كنعان عام 1922 اعتقاد بعض الأهالي أن يوسف أُلقي في جبٍّ قرب سنجل.', 'In 1922 Tawfiq Canaan recorded the belief of some villagers that Joseph was thrown into a pit near Sinjil.', NULL, 13),
  (NULL, 2, 'البلدة القديمة', 'The old town', 'historic_building', 'بلدة قديمة يسكنها نحو ثلاثين عائلة، وكانت مقرًّا محصّنًا لعائلة القاسم في القرن السابع عشر. (الصورة: Ramzi zeidan, CC BY-SA 4.0, Wikimedia Commons)', 'An old town where about thirty families live; it was a fortified base of the Qasim family in the 17th century. (Photo: Ramzi zeidan, CC BY-SA 4.0, Wikimedia Commons)', 'https://upload.wikimedia.org/wikipedia/commons/thumb/f/fd/Dayr_Istiya-26343.jpg/1280px-Dayr_Istiya-26343.jpg', 14),
  (NULL, 2, 'مسجد النبي الله أميسيا ومقام استيا', 'Mosque of Nabi Allah Amisiya and the maqam of Istiya', 'religious_site', 'مسجد غرب القرية من رواقين، ملاصق لمقام استيا الذي سُمّيت القرية باسمه.', 'A mosque west of the village with two aisles, next to the shrine of Istiya after which the village is named.', NULL, 14),
  (NULL, 2, 'مقام النبي خاطر', 'Shrine of Nabi Khatir', 'religious_site', 'على بُعد نحو 50 م شمال القرية، وتذكر نقوشه أن صاحبه توفي عام 1148م.', 'About 50 m north of the village; according to its inscriptions, the man buried there died in 1148 CE.', NULL, 14),
  (NULL, 3, 'المدرجات الزراعية ونظام الري القديم', 'Ancient terraces and irrigation system', 'natural_heritage', 'مدرجات حجرية تُروى بنظام يعود إلى العصر الروماني، تغذيه سبعة ينابيع وتوزّع مياهه بين العائلات بفتح البوابات يدويًا.', 'Stone terraces watered by a Roman-era system fed by seven springs; water is shared between families by opening sluice gates by hand.', NULL, 2),
  (NULL, 3, 'سكة حديد يافا - القدس', 'Jaffa-Jerusalem railway', 'historic_building', 'تمر السكة العثمانية تحت القرية في الوادي، وكانت خط الهدنة بين 1949 و1967. (الصورة: Hadi Hijjawi, CC BY-SA 4.0, Wikimedia Commons)', 'The Ottoman-era line runs through the valley below the village and served as the armistice line from 1949 to 1967. (Photo: Hadi Hijjawi, CC BY-SA 4.0, Wikimedia Commons)', 'https://upload.wikimedia.org/wikipedia/commons/b/bc/%D8%A8%D9%84%D8%AF%D8%A9_%D8%A8%D8%AA%D9%8A%D8%B1_-_%D8%BA%D8%B1%D8%A8_%D8%A8%D9%8A%D8%AA_%D9%84%D8%AD%D9%85.jpg', 15),
  (NULL, 3, 'عين البلد والحمام الروماني', 'Ein al-Balad and the Roman bath', 'archaeological_site', 'نبع القرية محاط ببيت نبع، وفي وسط القرية حمام روماني قديم يغذيه نبع.', 'The village spring is encased in a spring house, and an old Roman bath fed by a spring lies in the middle of the village.', NULL, 15),
  (NULL, 4, 'دير الحديقة المغلقة', 'Convent of the Hortus Conclusus', 'religious_site', 'دير مسيحي عبر الوادي من القرية بُني مطلع القرن العشرين، ويُستمد اسمه من اسم القرية «البستان». (الصورة: Artas Folklore Center, CC BY-SA 3.0, Wikimedia Commons)', 'A Christian convent across the valley from the village, built at the turn of the 20th century; its name echoes the village''s, "the garden". (Photo: Artas Folklore Center, CC BY-SA 3.0, Wikimedia Commons)', 'https://upload.wikimedia.org/wikipedia/commons/thumb/a/a2/The_Convent_of_the_Hortus_Conclusus_or_Sealed_Garden%2C_Artas_West_Bank%2C_Palestine.jpg/1280px-The_Convent_of_the_Hortus_Conclusus_or_Sealed_Garden%2C_Artas_West_Bank%2C_Palestine.jpg', 16),
  (NULL, 4, 'برك سليمان', 'Solomon''s Pools', 'archaeological_site', 'ثلاث برك قديمة قرب القرية كانت جزءًا من نظام ينقل المياه إلى بيت لحم والقدس، وكان أهل أرطاس يحرسونها حتى القرن التاسع عشر. (الصورة: Bukvoed, CC BY 4.0, Wikimedia Commons)', 'Three ancient reservoirs near the village, part of a system that carried water to Bethlehem and Jerusalem; the people of Artas guarded them until the 19th century. (Photo: Bukvoed, CC BY 4.0, Wikimedia Commons)', 'https://upload.wikimedia.org/wikipedia/commons/thumb/9/90/Solomons-Pools-MVIF-156.jpg/1280px-Solomons-Pools-MVIF-156.jpg', 16),
  (NULL, 6, 'الحصن', 'Al-Hisn (the castle)', 'historic_building', 'مبنى محصّن بفناء شمال غرب المسجد، يشرف على البلدة من أعلى نقطة فيها.', 'A fortified courtyard building north-west of the mosque, dominating the village from its highest point.', NULL, 18),
  (NULL, 6, 'المسجد القديم', 'The old mosque', 'religious_site', 'مسجد مبني على بقايا كنيسة بيزنطية، محرابه محاط بأعمدة رخامية وتيجان من العصر الصليبي.', 'A mosque built over a Byzantine church; its mihrab is flanked by marble columns and Crusader-period capitals.', NULL, 18),
  (NULL, 6, 'البركة', 'The pool (birka)', 'historic_building', 'بركة مكشوفة في وسط البلدة من آثارها الوسيطة.', 'An open cistern in the centre of the village, among its medieval remains.', NULL, 18),
  (NULL, 7, 'كنيسة القديس جورجيوس', 'Church of St George', 'religious_site', 'بُنيت في القرن السادس، وأصبحت بقاياها معلمًا سياحيًا، وتجري فيها حفريات أثرية منذ منتصف القرن التاسع عشر.', 'Built in the 6th century; its remains are a tourist attraction and have been excavated since the mid-19th century.', NULL, 19),
  (NULL, 7, 'برج جفنا', 'Burj Jifna', 'historic_building', 'برج من مبنى روماني قديم استخدمه العثمانيون سجنًا في القرن التاسع عشر.', 'The tower of an ancient Roman structure, used by the Ottomans as a jail in the 19th century.', NULL, 19),
  (NULL, 8, 'المسجد الكبير ومئذنته القديمة', 'The Great Mosque and its old minaret', 'religious_site', 'المسجد الكبير في البلدة القديمة ومئذنته القديمة. (الصورة: Yaqueen, CC BY-SA 4.0, Wikimedia Commons)', 'The Great Mosque of the old town and its old minaret. (Photo: Yaqueen, CC BY-SA 4.0, Wikimedia Commons)', 'https://upload.wikimedia.org/wikipedia/commons/thumb/8/88/Arch%C3%A9ologie.jpg/1280px-Arch%C3%A9ologie.jpg', 9),
  (NULL, 8, 'مقام الشيخ حمدان', 'Maqam Sheikh Hamdan', 'religious_site', 'مقام لرجل صالح محلي في البلدة.', 'The shrine of a local holy man.', NULL, 20),
  (NULL, 10, 'المدرج الروماني', 'Roman theatre', 'archaeological_site', 'مدرج من المدينة الرومانية، رمّمه علماء آثار أردنيون. (الصورة: Ovedc, CC BY-SA 4.0, Wikimedia Commons)', 'A theatre of the Roman city, restored by Jordanian archaeologists. (Photo: Ovedc, CC BY-SA 4.0, Wikimedia Commons)', 'https://upload.wikimedia.org/wikipedia/commons/thumb/2/27/2016_WLM_-_OVEDC_-_Ancient_Roman_theatre_of_Sebastia_033.jpg/1280px-2016_WLM_-_OVEDC_-_Ancient_Roman_theatre_of_Sebastia_033.jpg', 21),
  (NULL, 10, 'مسجد النبي يحيى', 'Nabi Yahya Mosque', 'religious_site', 'المسجد الرئيسي في القرية، قائم داخل بقايا كاتدرائية صليبية يُعتقد أنها بُنيت فوق قبور النبي اليسع وعوبديا ويوحنا المعمدان. (الصورة: Bukvoed, CC BY 4.0, Wikimedia Commons)', 'The village''s main mosque, standing within the remains of a Crusader cathedral believed to be built over the tombs of Elisha, Obadiah and John the Baptist. (Photo: Bukvoed, CC BY 4.0, Wikimedia Commons)', 'https://upload.wikimedia.org/wikipedia/commons/thumb/1/15/Sebastia-2-145.jpg/1280px-Sebastia-2-145.jpg', 21),
  (NULL, 10, 'تل السامرة الأثري', 'Archaeological mound of Samaria-Sebaste', 'archaeological_site', 'تل فيه بقايا من العصر البرونزي المبكر ومدينة العصر الحديدي والعصور الهلنستية والرومانية والبيزنطية، ومنه قطع «أوستراكا السامرة». (الصورة: Bukvoed, CC BY 3.0, Wikimedia Commons)', 'A tell with remains from the Early Bronze Age, the Iron Age city and the Hellenistic, Roman and Byzantine periods; the Samaria Ostraca were found here. (Photo: Bukvoed, CC BY 3.0, Wikimedia Commons)', 'https://upload.wikimedia.org/wikipedia/commons/thumb/9/96/Sebastia-393.jpg/1280px-Sebastia-393.jpg', 21),
  (NULL, 11, 'كنيسة القديسة مريم (ستّي مريم)', 'Church of St Mary (Sitti Miriam)', 'religious_site', 'كنيسة في وسط القرية تعود أصولها إلى القرنين الخامس والسادس، أُعيد بناؤها عام 1058، وأضاف إليها الصليبيون الصحن والرواق الشمالي.', 'A church in the village centre dating back to the 5th-6th century, rebuilt in 1058, to which the Crusaders added the nave and north aisle.', NULL, 22),
  (NULL, 11, 'مغارة عابود ومقبرة مقاطع عابود', 'Aboud cave and the Mokata Aboud necropolis', 'archaeological_site', 'مغارة ومقبرة قديمة قرب القرية من أواخر فترة الهيكل الثاني.', 'A cave and an ancient necropolis near the village from the late Second Temple period.', NULL, 22),
  (NULL, 11, 'الضريحان المملوكيان', 'The two Mamluk mausoleums', 'historic_building', 'ضريحان مزخرفان في الجزء الجنوبي من القرية الذي بُني في القرن الثالث عشر أو الرابع عشر.', 'Two ornate mausoleums in the southern part of the village, founded in the 13th or 14th century.', NULL, 22),
  (NULL, 12, 'خربة عين الكنيسة', 'Khirbet Ain al-Kanisah', 'archaeological_site', 'بقايا كنيسة شرق القرية بُنيت على مرحلتين: الأولى بين القرنين الخامس والسابع، والثانية بين الثامن والحادي عشر.', 'Remains of a church east of the village, built in two phases: the 5th-7th century and the 8th-11th century.', NULL, 23),
  (NULL, 12, 'ينابيع القرية', 'The village springs', 'natural_heritage', '11 نبعًا تروي مئات القطع الزراعية عبر شبكة من القنوات والسدود.', 'Eleven springs watering hundreds of small plots through a network of canals and dams.', NULL, 23),
  (NULL, 13, 'البلدة القديمة', 'Old Birzeit', 'historic_building', 'أكثر من مئة مبنى تاريخي يعود بعضها إلى العصر المملوكي، وفيها ست آبار قديمة لتخزين الزيت. رُمّمت عشرات المباني بعد انتقال الجامعة منها. (الصورة: Moataz1997, CC BY-SA 3.0, Wikimedia Commons)', 'Over a hundred historic buildings, some from the Mamluk era, and six old oil wells; dozens of buildings were restored after the university moved out. (Photo: Moataz1997, CC BY-SA 3.0, Wikimedia Commons)', 'https://upload.wikimedia.org/wikipedia/commons/thumb/d/d7/Old_Birzeit2.JPG/1280px-Old_Birzeit2.JPG', 24),
  (NULL, 13, 'كنيسة القديس جورجيوس الأرثوذكسية', 'St George Orthodox Church', 'religious_site', 'أقدم كنائس البلدة الثلاث، في البلدة القديمة. (الصورة: Moataz1997, CC BY-SA 3.0, Wikimedia Commons)', 'The oldest of the town''s three churches, in the old town. (Photo: Moataz1997, CC BY-SA 3.0, Wikimedia Commons)', 'https://upload.wikimedia.org/wikipedia/commons/thumb/8/83/St_George_Orthodox_Church_in_Old_Birzeit.JPG/1280px-St_George_Orthodox_Church_in_Old_Birzeit.JPG', 24),
  (NULL, 13, 'جامعة بيرزيت', 'Birzeit University', 'cultural_site', 'من أبرز الجامعات الفلسطينية، وتحمل اسم البلدة. (الصورة: The original uploader was Hannak at E..., CC BY-SA 3.0, Wikimedia Commons)', 'One of the leading Palestinian universities, named after the town. (Photo: The original uploader was Hannak at E..., CC BY-SA 3.0, Wikimedia Commons)', 'https://upload.wikimedia.org/wikipedia/commons/thumb/4/4c/Birzeit_University.jpg/1280px-Birzeit_University.jpg', 24),
  (NULL, 14, 'موقع جبعون الأثري والبركة', 'Gibeon archaeological site and pool', 'archaeological_site', 'موقع المدينة القديمة وفيه بركة وبئر ونظام مياه وأقبية نبيذ منحوتة في الصخر. رمّم الشباب والمسنّون من القرى المجاورة البركة خلال الانتفاضة الثانية. (الصورة: Ar2332, CC BY-SA 4.0, Wikimedia Commons)', 'The ancient city, with a pool, a well, a water system and rock-cut wine cellars; young people and elders from nearby villages restored the pool during the Second Intifada. (Photo: Ar2332, CC BY-SA 4.0, Wikimedia Commons)', 'https://upload.wikimedia.org/wikipedia/commons/thumb/c/cf/Gibeon_well_01.jpg/1280px-Gibeon_well_01.jpg', 25);
INSERT INTO `historical_events` (`id`, `village_id`, `title_ar`, `title_eng`, `description_ar`, `description_eng`, `event_date`, `source_id`) VALUES (17,9,'دخول القرية تحت الحكم العثماني','Incorporated into the Ottoman Empire','ضُمّت القرية مع سائر فلسطين إلى الدولة العثمانية. (السنة فقط موثّقة)','The village was incorporated into the Ottoman Empire with the rest of Palestine.  (Only the year is documented.)','1517-01-01',11);
INSERT INTO `historical_events` (`id`, `village_id`, `title_ar`, `title_eng`, `description_ar`, `description_eng`, `event_date`, `source_id`) VALUES (18,9,'تسجيل القرية في دفتر الضرائب العثماني','Recorded in the Ottoman tax register','ناحية جبل سامي، لواء نابلس: 55 أسرة مسلمة. دفعت ضريبة ثابتة بنسبة 33.3% على القمح والشعير والمحاصيل الصيفية والزيتون والنحل و/أو الماعز، بمجموع 9,372 أقجة، وذهب الريع إلى وقف مدرسة في الرملة. (السنة فقط موثّقة)','Nahiya of Jabal Sami, Liwa of Nablus: 55 Muslim households. A fixed 33.3% tax on wheat, barley, summer crops, olive trees, beehives and/or goats, 9,372 akçe in total, paid to a waqf for a madrasa in Ramla.  (Only the year is documented.)','1596-01-01',11);
INSERT INTO `historical_events` (`id`, `village_id`, `title_ar`, `title_eng`, `description_ar`, `description_eng`, `event_date`, `source_id`) VALUES (19,9,'وصف القرية في مسح فلسطين الغربية','Described in the Survey of Western Palestine','قرية صغيرة في منخفض، فوقها نبع يبدو دائمًا تُروى منه حدائق الخضار، ويزرع حولها التين والزيتون. (السنة فقط موثّقة)','A small village in a hollow, with an apparently perennial spring above it irrigating vegetable gardens; figs and olives grow nearby.  (Only the year is documented.)','1882-01-01',11);
INSERT INTO `historical_events` (`id`, `village_id`, `title_ar`, `title_eng`, `description_ar`, `description_eng`, `event_date`, `source_id`) VALUES (20,9,'تأسيس المجلس القروي','Village council founded','يدير المجلس شؤون القرية وخدماتها منذ تأسيسه. (السنة فقط موثّقة)','The council has run the village\'s affairs and services since then.  (Only the year is documented.)','1964-01-01',12);
INSERT INTO `historical_events` (`id`, `village_id`, `title_ar`, `title_eng`, `description_ar`, `description_eng`, `event_date`, `source_id`) VALUES (21,9,'الاحتلال الإسرائيلي','Israeli occupation','وقعت القرية تحت الاحتلال الإسرائيلي بعد حرب 1967. (السنة فقط موثّقة)','The village came under Israeli occupation after the 1967 war.  (Only the year is documented.)','1967-01-01',11);
INSERT INTO `historical_events` (`id`, `village_id`, `title_ar`, `title_eng`, `description_ar`, `description_eng`, `event_date`, `source_id`) VALUES (22,9,'إنشاء شبكة المياه العامة','Public water network established','تزوّد بلدية نابلس القرية بالمياه، و95% من الأسر موصولة بالشبكة (2013). (السنة فقط موثّقة)','Nablus Municipality supplies the water; 95% of households were connected in 2013.  (Only the year is documented.)','1970-01-01',12);
INSERT INTO `historical_events` (`id`, `village_id`, `title_ar`, `title_eng`, `description_ar`, `description_eng`, `event_date`, `source_id`) VALUES (23,9,'وصل القرية بشبكة الكهرباء','Connected to the electricity grid','جميع الوحدات السكنية موصولة بالشبكة (2013). (السنة فقط موثّقة)','All housing units were connected by 2013.  (Only the year is documented.)','1976-01-01',12);
INSERT INTO `historical_events` (`id`, `village_id`, `title_ar`, `title_eng`, `description_ar`, `description_eng`, `event_date`, `source_id`) VALUES (24,9,'إقامة مستوطنة شافي شومرون','Shavei Shomron settlement founded','صودر 236 دونمًا من أراضي القرية للمستوطنة الواقعة إلى الشمال منها، ثم 16 دونمًا لقاعدة عسكرية قربها. (السنة فقط موثّقة)','236 dunums of village land were confiscated for the settlement north of the village, and 16 more for a military base near it.  (Only the year is documented.)','1977-01-01',12);
INSERT INTO `historical_events` (`id`, `village_id`, `title_ar`, `title_eng`, `description_ar`, `description_eng`, `event_date`, `source_id`) VALUES (25,9,'اتفاقية أوسلو الثانية','Oslo II Accord','صُنّف نحو 1,827 دونمًا (24%) مناطق (ب) و5,918 دونمًا (76%) مناطق (ج).','About 1,827 dunums (24%) were classified as Area B and 5,918 dunums (76%) as Area C.','1995-09-28',12);
INSERT INTO `historical_events` (`id`, `village_id`, `title_ar`, `title_eng`, `description_ar`, `description_eng`, `event_date`, `source_id`) VALUES (26,9,'إنشاء شبكة الصرف الصحي','Public sewerage network built','تغطي الشبكة نحو 75% من القرية (2013). (السنة فقط موثّقة)','It reached about 75% of the village by 2013.  (Only the year is documented.)','1997-01-01',12);
INSERT INTO `historical_events` (`id`, `village_id`, `title_ar`, `title_eng`, `description_ar`, `description_eng`, `event_date`, `source_id`) VALUES (27,9,'أمر عسكري بمصادرة 53.4 دونمًا','Military order confiscating 53.4 dunums','الأمر رقم 165/05/ت صادر 53.4 دونمًا من أراضي دير شرف وسبسطية والناقورة لإقامة «منطقة أمنية» لمستوطنة شافي شومرون.','Order 165/05/T took 53.4 dunums of Deir Sharaf, Sabastiya and An Naqura land for a \"security zone\" around Shavei Shomron.','2005-09-20',12);
INSERT INTO `historical_events` (`id`, `village_id`, `title_ar`, `title_eng`, `description_ar`, `description_eng`, `event_date`, `source_id`) VALUES (28,9,'استئناف العمل في مكبّ النفايات غرب القرية','Landfill west of the village reopened','مكبّ على مساحة 150 دونمًا على بُعد نحو 500 م من البيوت، في منطقة غنية بالمياه الجوفية، استُؤنف العمل فيه بعد توقّف قصير. (السنة فقط موثّقة)','A 150-dunum landfill about 500 m from the houses, over important groundwater, resumed operations after a short suspension.  (Only the year is documented.)','2009-01-01',12);
INSERT INTO `historical_events` (`id`, `village_id`, `title_ar`, `title_eng`, `description_ar`, `description_eng`, `event_date`, `source_id`) VALUES (29,9,'أمر عسكري بمصادرة 137 دونمًا','Military order confiscating 137 dunums','الأمر رقم 95/26/ت صادر 137 دونمًا من أراضي دير شرف وقوصين وكفر قدوم لشق طريق التفافي يربط المستوطنات.','Order 95/26/T took 137 dunums of Deir Sharaf, Qusin and Kafr Qaddum land for a bypass road linking the settlements.','2012-09-18',12);
INSERT INTO `historical_events` (`id`, `village_id`, `title_ar`, `title_eng`, `description_ar`, `description_eng`, `event_date`, `source_id`) VALUES (30,9,'إعلان مصادرة 16 دونمًا لأغراض عسكرية','Confiscation of 16 dunums announced','أعلنت السلطات الإسرائيلية نيتها مصادرة 16 دونمًا قرب القرية «لأغراض عسكرية».','Israeli authorities announced the confiscation of 16 dunums near the village \"for military purposes\".','2014-07-03',11);
INSERT INTO `historical_events` (`village_id`, `title_ar`, `title_eng`, `description_ar`, `description_eng`, `event_date`, `source_id`) VALUES
  (1, 'نقل عشور الأبرشية إلى دير جبل طابور', 'Parish tithes transferred to Mount Tabor', 'نُقلت كنيسة الأبرشية وعشورها من كنيسة القيامة إلى دير جبل طابور. (السنة فقط موثّقة)', 'The parish church and its tithes were transferred from the Holy Sepulchre to the monastery on Mount Tabor. (Only the year is documented.)', '1145-01-01', 13),
  (1, 'إعادة بيع الأبرشية لكنيسة القيامة', 'Parish sold back to the Holy Sepulchre', 'أُعيدت الأبرشية وعشورها إلى كنيسة القيامة بسبب البُعد وارتفاع التكاليف. (السنة فقط موثّقة)', 'The parish and its tithes were sold back to the Holy Sepulchre because of the distance and costs. (Only the year is documented.)', '1175-01-01', 13),
  (1, 'تسجيل القرية في دفتر الضرائب العثماني', 'Recorded in the Ottoman tax register', 'ظهرت في ناحية القدس من لواء القدس. (السنة فقط موثّقة)', 'Listed in the nahiya of Quds, Liwa of Quds. (Only the year is documented.)', '1596-01-01', 4),
  (1, 'زيارة الرحالة فكتور غيرين', 'Visit of Victor Guérin', 'وصفها بأنها «مزدحمة» وقدّر سكانها بنحو 1,200 نسمة، ولاحظ على قمة التل أساسات حصنين قديمين يُسمّيان القصر والكنيسة. (السنة فقط موثّقة)', 'He described it as "quite crowded", with about 1,200 villagers, and noted the foundations of two ancient strongholds on the hilltop called the Kasr and the Keniseh. (Only the year is documented.)', '1870-01-01', 13),
  (1, 'وصف القرية في مسح فلسطين الغربية', 'Described in the Survey of Western Palestine', 'قرية متوسطة الحجم فيها بيوت من طابقين، على سفح تل تحته بساتين تين جميلة. (السنة فقط موثّقة)', 'A village of moderate size with several two-storey houses, on a hillside with fine fig gardens below. (Only the year is documented.)', '1882-01-01', 7),
  (2, 'وقف للمسجد الإبراهيمي', 'Waqf for the Ibrahimi Mosque', 'أمر السلطان المملوكي برقوق القرية بتقديم العدس وزيت الزيتون والطحين وقفًا للمسجد الإبراهيمي في الخليل. (السنة فقط موثّقة)', 'The Mamluk sultan Barquq required the village to supply lentils, olive oil and flour as a waqf for the Ibrahimi Mosque in Hebron. (Only the year is documented.)', '1394-01-01', 14),
  (2, 'تسجيل القرية في دفتر الضرائب العثماني', 'Recorded in the Ottoman tax register', 'ظهرت باسم «دير استيا» في ناحية جبل قبال من لواء نابلس، ودفعت 23,860 أقجة. (السنة فقط موثّقة)', 'Listed as Dayr Istya in the nahiya of Jabal Qubal, Sanjak of Nablus, paying 23,860 akçe. (Only the year is documented.)', '1596-01-01', 4),
  (2, 'وصف القرية في مسح فلسطين الغربية', 'Described in the Survey of Western Palestine', 'قرية كبيرة على أرض مرتفعة تحيط بها كروم الزيتون وتعتمد على الآبار. (السنة فقط موثّقة)', 'A large village on high ground, surrounded with olive groves and supplied by cisterns. (Only the year is documented.)', '1882-01-01', 7),
  (2, '«برلين الصغيرة»', '"Little Berlin"', 'بين 1950 و1960 برز الحزب الشيوعي الفلسطيني في القرية فلُقّبت محليًا بـ«برلين الصغيرة». (السنة فقط موثّقة)', 'From 1950 to 1960 the Palestine Communist Party was prominent in the village, which was locally nicknamed "Little Berlin". (Only the year is documented.)', '1950-01-01', 14),
  (2, 'أوامر باقتلاع أشجار الزيتون', 'Orders to uproot olive trees', 'أمرت الإدارة المدنية الإسرائيلية باقتلاع أكثر من 1,000 شجرة زيتون في منطقة وادي قانا. (السنة فقط موثّقة)', 'The Israeli Civil Administration ordered villagers to uproot more than 1,000 olive trees in the Wadi Qana area. (Only the year is documented.)', '2012-01-01', 14),
  (3, 'تسجيل القرية في دفتر الضرائب العثماني', 'Recorded in the Ottoman tax register', 'ظهرت في ناحية القدس من لواء القدس. (السنة فقط موثّقة)', 'Listed in the nahiya of Quds, Liwa of Quds. (Only the year is documented.)', '1596-01-01', 4),
  (3, 'زيارة الرحالة فكتور غيرين', 'Visit of Victor Guérin', 'وصف القرية على جبل شديد الانحدار يشرف عليها لسان صخري ما زالت فيه بقايا أسوار قديمة. (السنة فقط موثّقة)', 'He described the village on a steep mountain, overlooked by a rocky spur that still held remains of old walls. (Only the year is documented.)', '1863-01-01', 15),
  (3, 'ضمّ القرية إلى الأردن', 'Annexed by Jordan', 'أصبحت تحت الإدارة الأردنية بعد حرب 1948 وضُمّت عام 1950، على بُعد أمتار من خط الهدنة. (السنة فقط موثّقة)', 'It came under Jordanian rule after the 1948 war and was annexed in 1950, a few metres from the armistice line. (Only the year is documented.)', '1950-01-01', 15),
  (3, 'جائزة اليونسكو لحماية المشهد الثقافي', 'UNESCO prize for its cultural landscape', 'منحت اليونسكو بتير جائزة بقيمة 15,000 دولار لحماية مدرجاتها ونظام ريّها القديم وإدارتهما. (السنة فقط موثّقة)', 'UNESCO awarded Battir a $15,000 prize for safeguarding and managing its ancient terraces and irrigation system. (Only the year is documented.)', '2011-01-01', 15),
  (3, 'إدراج بتير في قائمة التراث العالمي', 'Battir inscribed on the World Heritage List', 'سُجّلت باسم «فلسطين: أرض الزيتون والكروم - المشهد الثقافي لجنوب القدس، بتير».', 'Inscribed as "Palestine: Land of Olives and Vines - Cultural Landscape of Southern Jerusalem, Battir".', '2014-06-20', 2),
  (4, 'تأكيد منح القرية لكنيسة بيت لحم', 'Village confirmed to the Church of Bethlehem', 'أكّد البابا غريغوري التاسع أن القرية مُنحت لكنيسة بيت لحم. (السنة فقط موثّقة)', 'Pope Gregory IX confirmed that the village had been given to the Church of Bethlehem. (Only the year is documented.)', '1227-01-01', 16),
  (4, 'زيارة الرحالة فكتور غيرين', 'Visit of Victor Guérin', 'وجد فيها نحو 300 نسمة. (السنة فقط موثّقة)', 'He found about 300 inhabitants. (Only the year is documented.)', '1863-01-01', 16),
  (4, 'وصف القرية في مسح فلسطين الغربية', 'Described in the Survey of Western Palestine', 'قرية صغيرة على سفح تل، خلفها نبع جيد تخرج منه قناة إلى جبل الفريديس، وبقايا خزان حمّام سليمان. (السنة فقط موثّقة)', 'A small village against a hillside with a good spring behind it, an aqueduct to Jebel Furedis and the remains of a reservoir. (Only the year is documented.)', '1883-01-01', 7),
  (4, 'اختتام دراسة هيلما غرانكفيست', 'Hilma Granqvist completes her fieldwork', 'وثّقت الباحثة الفنلندية حياة القرية بكل جوانبها والتقطت مئات الصور، ونُشرت كتبها عن أرطاس بين 1931 و1965. (السنة فقط موثّقة)', 'The Finnish researcher documented every aspect of village life and took hundreds of photographs; her books on Artas appeared between 1931 and 1965. (Only the year is documented.)', '1931-01-01', 16),
  (4, 'تأسيس مركز أرطاس للتراث الشعبي', 'Artas Folklore Center founded', 'يضم المركز متحفًا صغيرًا للتراث وفرقة دبكة وفرقة مسرح. (السنة فقط موثّقة)', 'The centre has a small folklore museum, a dabka troupe and a drama troupe. (Only the year is documented.)', '1993-01-01', 16),
  (4, 'أول مهرجان للخس', 'First Lettuce Festival', 'أصبح مهرجان الخس حدثًا سنويًا منذ عام 1994. (السنة فقط موثّقة)', 'The Artas Lettuce Festival has been held every year since 1994. (Only the year is documented.)', '1994-01-01', 16),
  (5, 'تسجيل القرية في دفتر الضرائب العثماني', 'Recorded in the Ottoman tax register', 'ظهرت في ناحية جبل قبال من لواء نابلس، ودفعت ضرائب على القمح والشعير والزيتون ومعصرة، بمجموع 8,000 أقجة. (السنة فقط موثّقة)', 'Listed in the nahiya of Jabal Qubal, Liwa of Nablus, paying taxes on wheat, barley, olive trees and a press, 8,000 akçe in total. (Only the year is documented.)', '1596-01-01', 4),
  (5, 'زيارة إدوارد روبنسون', 'Visit of Edward Robinson', 'وصفها بأنها «قرية كبيرة» في ناحية البيتاوي شرق نابلس. (السنة فقط موثّقة)', 'He noted it as a "large village" in the El-Beitawy district, east of Nablus. (Only the year is documented.)', '1838-01-01', 17),
  (5, 'وصف القرية في مسح فلسطين الغربية', 'Described in the Survey of Western Palestine', 'قرية كبيرة لها ضاحية في الجنوب قربها مقابر قديمة، وهي قاعدة الناحية المسمّاة باسمها. (السنة فقط موثّقة)', 'A large village with a kind of suburb to the south near ancient tombs, the capital of the district named from it. (Only the year is documented.)', '1882-01-01', 7),
  (5, 'الاحتجاج على بؤرة أفيتار', 'Protests against the Evyatar outpost', 'قُتل سبعة من أهل البلدة بين أيار وأيلول 2021 خلال قمع المظاهرات ضد إقامة البؤرة الاستيطانية على أراضيها. (السنة فقط موثّقة)', 'Seven residents were killed between May and September 2021 as protests against the outpost on the town''s land were suppressed. (Only the year is documented.)', '2021-01-01', 17),
  (6, 'نقش بناء مملوكي', 'Mamluk building inscription', 'عُثر في البلدة على نقش بناء عربي يعود إلى عام 1414 وكسر فخارية مملوكية. (السنة فقط موثّقة)', 'An Arabic building inscription dated 1414 and Mamluk pottery were found in the town. (Only the year is documented.)', '1414-01-01', 18),
  (6, 'تسجيل البلدة في الإحصاء العثماني', 'Recorded in the Ottoman census', 'ناحية جبل قبال، لواء نابلس: 102 أسرة مسلمة، بضرائب مجموعها 3,960 أقجة. (السنة فقط موثّقة)', 'Nahiya of Jabal Qubal, Sanjak Nablus: 102 Muslim households, paying 3,960 akçe in taxes. (Only the year is documented.)', '1596-01-01', 4),
  (6, 'زيارة الرحالة فكتور غيرين', 'Visit of Victor Guérin', 'وصفها بأنها بلدة كبيرة يسكنها نحو 2,000 نسمة. (السنة فقط موثّقة)', 'He described a large town with about 2,000 inhabitants. (Only the year is documented.)', '1870-01-01', 18),
  (6, 'وصف البلدة في مسح فلسطين الغربية', 'Described in the Survey of Western Palestine', 'قرية كبيرة تحيط بها أشجار الزيتون، بيوتها أحسن بناءً من معظم بيوت البلاد، وفي شرقها مسجد قائم على بقايا كنيسة. (السنة فقط موثّقة)', 'A large village surrounded with olives, with houses better built than most, and a mosque founded on the remains of a church. (Only the year is documented.)', '1882-01-01', 7),
  (6, 'إحراق مسجد في البلدة', 'Village mosque set on fire', 'أُحرق مسجد في البلدة في تشرين الأول 2014 في اعتداء يُشتبه أن مستوطنين نفّذوه. (السنة فقط موثّقة)', 'A village mosque was set alight in October 2014 in a suspected settler arson attack. (Only the year is documented.)', '2014-01-01', 18),
  (7, 'احتلال فسبازيان للبلدة', 'Occupied by Vespasian', 'احتلها الإمبراطور الروماني فسبازيان وأقام فيها حامية. (السنة فقط موثّقة)', 'The Roman emperor Vespasian occupied the town and set up a garrison there. (Only the year is documented.)', '0068-01-01', 19),
  (7, 'تسجيل القرية في دفتر الضرائب العثماني', 'Recorded in the Ottoman tax register', 'باسم «جفنا النصارى» في ناحية القدس، بـ21 أسرة. (السنة فقط موثّقة)', 'Listed as "Jifna an-Nasara" in the nahiya of Jerusalem, with 21 households. (Only the year is documented.)', '1596-01-01', 4),
  (7, 'بناء الكنيسة الأرثوذكسية', 'Orthodox church built', 'بُنيت في القرية كنيسة أرثوذكسية شرقية، ثم كنيسة لاتينية أكبر. (السنة فقط موثّقة)', 'An Eastern Orthodox church was built in the village, followed by a larger Latin church. (Only the year is documented.)', '1858-01-01', 19),
  (7, 'وصف القرية في مسح فلسطين الغربية', 'Described in the Survey of Western Palestine', 'قرية مسيحية مهمة فيها كنيسة لاتينية ودير. (السنة فقط موثّقة)', 'An important Christian village with a Latin church and a convent. (Only the year is documented.)', '1882-01-01', 7),
  (8, 'تسجيل القرية في دفتر الضرائب العثماني', 'Recorded in the Ottoman tax register', 'ناحية جبل قبال، لواء نابلس، بضرائب مجموعها 2,700 أقجة. (السنة فقط موثّقة)', 'Nahiya of Jabal Qubal, Liwa of Nablus, paying 2,700 akçe in taxes. (Only the year is documented.)', '1596-01-01', 4),
  (8, 'زيارة إدوارد روبنسون', 'Visit of Edward Robinson', 'ذكرها قرية باسم «بديا» في ناحية جورة مرداء جنوب نابلس. (السنة فقط موثّقة)', 'He noted it as a village, Bidia, in the Jurat Merda district south of Nablus. (Only the year is documented.)', '1838-01-01', 20),
  (8, 'وصف القرية في مسح فلسطين الغربية', 'Described in the Survey of Western Palestine', 'قرية متوسطة الحجم بيوتها من الحجر، تحيط بها بساتين زيتون قديمة، وتعتمد على آبار منحوتة في الصخر. (السنة فقط موثّقة)', 'A village of moderate size, houses principally of stone, surrounded with fine old olives; water from rock-cut cisterns. (Only the year is documented.)', '1882-01-01', 7),
  (10, 'تسجيل القرية في دفتر الضرائب العثماني', 'Recorded in the Ottoman tax register', 'ناحية جبل سامي، لواء نابلس، بضرائب على القمح والشعير والزيتون مجموعها 5,500 أقجة. (السنة فقط موثّقة)', 'Nahiya of Jabal Sami, Sanjak Nablus, paying taxes on wheat, barley and olive trees, 5,500 akçe in total. (Only the year is documented.)', '1596-01-01', 4),
  (10, 'وصف القرية في مسح فلسطين الغربية', 'Described in the Survey of Western Palestine', 'قرية كبيرة مزدهرة من بيوت الحجر والطين على تل السامرة القديمة، وإلى شمالها الغربي أطلال كاتدرائية القديس يوحنا الصليبية. (السنة فقط موثّقة)', 'A large and flourishing village of stone and mud houses on the hill of ancient Samaria, with the ruins of the Crusader Cathedral of St John to the north-west. (Only the year is documented.)', '1882-01-01', 7),
  (10, 'بدء تنقيبات بعثة هارفارد', 'Harvard Expedition excavations begin', 'نقّبت بعثة جامعة هارفارد في الموقع بقيادة غوتليب شوماخر ثم جورج رايزنر حتى 1910. (السنة فقط موثّقة)', 'The Harvard Expedition excavated the site under Gottlieb Schumacher and then George Reisner until 1910. (Only the year is documented.)', '1908-01-01', 21),
  (10, 'إدراج سبسطية على قائمة التراث العالمي', 'Sebastia inscribed on the World Heritage List', 'أدرجتها اليونسكو موقعًا للتراث العالمي وصنّفتها فورًا موقعًا مهدّدًا بالخطر. (السنة فقط موثّقة)', 'UNESCO designated it a World Heritage Site and immediately classified it as endangered. (Only the year is documented.)', '2026-01-01', 21),
  (11, 'إعادة بناء كنيسة القديسة مريم', 'Church of St Mary rebuilt', 'يذكر نقش آرامي في الكنيسة أنها أُعيد بناؤها في العهد الفاطمي. (السنة فقط موثّقة)', 'An Aramaic inscription in the church records its rebuilding under Fatimid rule. (Only the year is documented.)', '1058-01-01', 22),
  (11, 'زيارة الرحالة فكتور غيرين', 'Visit of Victor Guérin', 'وجد فيها نحو 800 نسمة نصفهم من الروم الأرثوذكس ونصفهم مسلمون. (السنة فقط موثّقة)', 'He found about 800 inhabitants, half Greek Orthodox and half Muslim. (Only the year is documented.)', '1870-01-01', 22),
  (11, 'وصف القرية في مسح فلسطين الغربية', 'Described in the Survey of Western Palestine', 'قرية مسيحية كبيرة مزدهرة من الحجر، معظم بيوتها موسومة بالصليب بالطلاء الأحمر. (السنة فقط موثّقة)', 'A large and flourishing Christian village of stone, the houses nearly all marked with the Cross in red paint. (Only the year is documented.)', '1882-01-01', 7),
  (11, 'ترميم كنيسة القديسة مريم', 'Restoration of the Church of St Mary', 'كشفت أعمال الترميم بقايا كنيسة بيزنطية بأرضيات فسيفساء. (السنة فقط موثّقة)', 'Restoration work uncovered the remains of a Byzantine church with mosaic floors. (Only the year is documented.)', '1997-01-01', 22),
  (12, 'تسجيل القرية في الإحصاء العثماني', 'Recorded in the Ottoman census', 'باسم «فوقين» في ناحية القدس، بضرائب على القمح والشعير والزيتون والدبس مجموعها 2,280 أقجة. (السنة فقط موثّقة)', 'Listed as Fuqin in the nahiya of Quds, paying taxes on wheat, barley, olives and grape syrup, 2,280 akçe in total. (Only the year is documented.)', '1596-01-01', 4),
  (12, 'وصف القرية في مسح فلسطين الغربية', 'Described in the Survey of Western Palestine', 'قرية حجرية صغيرة على سفح تل، تحتها نبع جيد قربه بساتين برتقال وليمون، وإلى الشرق نبع ثانٍ هو عين الكنيسة. (السنة فقط موثّقة)', 'A small stone village on a hillside with a good spring below, orange and lemon gardens near it, and a second spring, Ain el Keniseh, to the east. (Only the year is documented.)', '1883-01-01', 7),
  (12, 'قرار لجنة الهدنة المشتركة', 'Mixed Armistice Commission ruling', 'قررت اللجنة بالأغلبية أن إسرائيل خرقت اتفاقية الهدنة بطرد أهل القرية، وأنه يجب السماح لهم بالعودة.', 'The commission ruled by majority that Israel had violated the armistice by expelling the villagers, and that they should be allowed to return.', '1949-08-31', 23),
  (12, 'العودة ثم التهجير من جديد', 'Return and second expulsion', 'عاد الأهالي بإشراف مراقبي الأمم المتحدة فوجدوا معظم بيوتهم مهدّمة، وأجبرهم الجيش الإسرائيلي على العودة إلى الجانب الأردني.', 'Villagers returned under UN supervision, found most houses destroyed, and were forced back to the Jordanian side by the Israeli army.', '1949-09-06', 23),
  (12, 'عودة الأهالي إلى القرية', 'Villagers return', 'سُمح للأهالي بالعودة شرط أن يبنوا بيوتهم خلال شهر. (السنة فقط موثّقة)', 'The inhabitants were allowed to return on condition that they build their homes within a month. (Only the year is documented.)', '1972-01-01', 23),
  (13, 'تسجيل القرية في دفتر الضرائب العثماني', 'Recorded in the Ottoman tax register', 'باسم «بير زيت» في ناحية جبل القدس، بـ26 أسرة. (السنة فقط موثّقة)', 'Listed as Bir Zayt in the nahiya of Jabal Quds, with 26 households. (Only the year is documented.)', '1596-01-01', 4),
  (13, 'تأسيس كنيسة سيدة السلام (غوادالوبي)', 'Church of Our Lady Queen of Peace founded', 'كنيسة كاثوليكية تدير أيضًا مدرسة ثانوية. (السنة فقط موثّقة)', 'A Catholic church that also runs a high school. (Only the year is documented.)', '1858-01-01', 24),
  (13, 'زيارة الرحالة فكتور غيرين', 'Visit of Victor Guérin', 'زار الرحالة الفرنسي القرية في تموز 1863. (السنة فقط موثّقة)', 'The French explorer visited the village in July 1863. (Only the year is documented.)', '1863-01-01', 24),
  (13, 'وصف القرية في مسح فلسطين الغربية', 'Described in the Survey of Western Palestine', 'قرية مسيحية متوسطة الحجم فيها كنيسة يونانية وكنيسة لاتينية، وبئر في شمالها، وتحيط بها أشجار الزيتون. (السنة فقط موثّقة)', 'A Christian village of moderate size with a Greek and a Latin church, a well to the north, and olives round it. (Only the year is documented.)', '1882-01-01', 7),
  (14, 'توقف صلاح الدين في الجيب', 'Saladin halts at al-Jib', 'بعد سقوط القدس توقف السلطان الأيوبي صلاح الدين في الجيب قبل أن يتابع إلى بيت نوبا. (السنة فقط موثّقة)', 'After the fall of Jerusalem the Ayyubid sultan Saladin halted at al-Jib before continuing to Beit Nuba. (Only the year is documented.)', '1187-01-01', 25),
  (14, 'تسجيل القرية في دفتر الضرائب العثماني', 'Recorded in the Ottoman tax register', 'باسم «جيب» في ناحية جبل القدس، بضرائب مجموعها 16,060 أقجة. (السنة فقط موثّقة)', 'Listed as Jib in the nahiya of Jabal Quds, paying 16,060 akçe in taxes. (Only the year is documented.)', '1596-01-01', 4),
  (14, 'مطابقة الجيب مع جبعون', 'Al-Jib identified with Gibeon', 'كان إدوارد روبنسون أول من طابق الجيب علميًا مع مدينة جبعون القديمة. (السنة فقط موثّقة)', 'Edward Robinson made the first scientific identification of al-Jib with ancient Gibeon. (Only the year is documented.)', '1838-01-01', 25),
  (14, 'حفريات جيمس بريتشارد', 'James Pritchard''s excavations', 'أكدت حفريات 1956 و1957 و1959 المطابقة بالعثور على 56 مقبض جرّة منقوشًا باسم «جبعون». (السنة فقط موثّقة)', 'Excavations in 1956, 1957 and 1959 confirmed the identification with 56 jar handles inscribed with the name Gibeon. (Only the year is documented.)', '1956-01-01', 25);
INSERT INTO `historical_events` (`village_id`, `title_ar`, `title_eng`, `description_ar`, `description_eng`, `event_date`, `source_id`) VALUES
  (10, 'إعادة بناء المدينة على يد هيرودس (27 ق.م)', 'Herod rebuilds the city (27 BCE)', 'أعاد هيرودس الكبير بناء المدينة وسمّاها سبسطية تكريمًا للإمبراطور أغسطس.', 'Herod the Great rebuilt the city and named it Sebastia in honour of the emperor Augustus.', NULL, 21);
INSERT INTO `cultural_practices` (`id`, `village_id`, `category`, `name_ar`, `name_eng`, `description_ar`, `description_eng`, `source_id`) VALUES
  (1, 9, 'agricultural-practice', 'زراعة الزيتون', 'Olive cultivation', 'تشتهر دير شرف بزراعة الزيتون، وتغطي أشجاره نحو 3,295 دونمًا من أراضيها (وزارة الزراعة، 2010، عبر ملف أريج). وفي القرية معصرة زيتون.', 'Deir Sharaf is known for olive growing: olive trees cover about 3,295 dunums of its land (Ministry of Agriculture, 2010, via the ARIJ profile). The village has an olive press.', 12),
  (2, 9, 'agricultural-practice', 'حدائق الخضار المرويّة من النبع', 'Vegetable gardens irrigated from the spring', 'وصف مسح فلسطين الغربية (1882) نبعًا يبدو دائمًا فوق القرية تُروى منه حدائق الخضار، ويزرع حولها التين والزيتون.', 'The Survey of Western Palestine (1882) described an apparently perennial spring above the village watering vegetable gardens, with figs and olives growing nearby.', 11),
  (NULL, 2, 'agricultural-practice', 'زراعة الزيتون منذ العصر المملوكي', 'Olive farming since the Mamluk era', 'دير استيا مركز لزراعة الزيتون منذ العصر المملوكي، وتُبذل جهود لتسويق زيتها في أوروبا تحت علامة «زيتون» للتجارة العادلة.', 'Deir Istiya has been a centre of olive farming since the Mamluk era; there are efforts to market its oil in Europe under the Zaytoun Fairtrade label.', 14),
  (NULL, 3, 'food', 'الباذنجان البتيري', 'Battiri eggplant', 'صنف محلي مستطيل بلون بنفسجي فاتح ولبّ أبيض طري قليل البذور، يدخل في أطباق فلسطينية مثل المقلوبة.', 'A local elongated, light-purple variety with soft, seedless white flesh, used in Palestinian dishes such as maqluba.', 15),
  (NULL, 3, 'custom', 'مهرجان الباذنجان', 'Eggplant Festival', 'مهرجان صيفي سنوي يدعم المزارعين والمنتجين المحليين ويحتفي بزراعة الباذنجان البتيري.', 'An annual summer festival supporting local farmers and producers and celebrating the Battiri eggplant.', 15),
  (NULL, 3, 'agricultural-practice', 'الري التقليدي بالدور', 'Traditional rotating irrigation', 'توزَّع مياه الينابيع على العائلات بالدور عبر قنوات وبوابات تُفتح يدويًا، ومن هنا القول الشائع إن «الأسبوع في بتير ثمانية أيام».', 'Spring water is shared between families in turns through channels and hand-opened gates; hence the saying that in Battir "a week lasts eight days".', 15),
  (NULL, 4, 'custom', 'مهرجان الخس', 'Artas Lettuce Festival', 'حدث سنوي منذ عام 1994 ينظمه مركز أرطاس للتراث الشعبي.', 'An annual event since 1994, organised by the Artas Folklore Center.', 16),
  (NULL, 4, 'music-dance', 'فرقة أرطاس للدبكة', 'Artas dabka troupe', 'فرقة دبكة تابعة لمركز أرطاس للتراث الشعبي الذي تأسس عام 1993.', 'A dabka troupe of the Artas Folklore Center, founded in 1993.', 16),
  (NULL, 7, 'custom', 'مهرجان قطف المشمش', 'Apricot harvest festival', 'في أواخر الربيع يقصد المئات القرية لقطف المشمش خلال موسمه القصير.', 'In late spring, hundreds travel to the village to pick apricots during their brief season.', 19),
  (NULL, 8, 'craft', 'الصابون النابلسي', 'Nabulsi soap', 'من الصناعات الرئيسية في البلدة، ويُصنع من زيت الزيتون المحلي.', 'One of the town''s main industries, made from local olive oil.', 20),
  (NULL, 11, 'craft', 'صابون زيت الزيتون', 'Olive oil soap', 'من المنتجات الرئيسية للقرية القائم اقتصادها تاريخيًا على الزيتون.', 'One of the main products of a village whose economy has centred on olives.', 22),
  (NULL, 12, 'agricultural-practice', 'الري من الينابيع بالقنوات والسدود', 'Spring irrigation through canals and dams', 'تُروى مئات القطع الصغيرة من 11 نبعًا، وأُدخل الري بالتنقيط والزراعة العضوية بمساعدة مؤسسات زراعية.', 'Eleven springs water hundreds of small plots; drip irrigation and organic methods were introduced with the help of farming organisations.', 23);
